const gradePreviewMaterialsJson =
    r'''[{"id": "a2606d99-ea89-5911-ba99-dd7a02cab3d6", "owner_id": null, "kind": "lesson", "title": "Grade 1: Animal friends", "grade_level": 1, "learning_level": "beginner", "summary": "Four bilingual learning pages with examples and a practice task.", "source_label": "LinguaKids grade pathways · original supplemental enrichment v3", "body": {"cover_scene": 0, "unit_title": "Animal friends", "pages": [{"english": "A noun names an animal, person, place, or thing. Today we will name four animal friends: cat, dog, bird, and fish.", "filipino": "Ang pangngalan ay ngalan ng hayop, tao, lugar, o bagay. Ngayon ay kikilalanin natin ang apat na kaibigang hayop: pusa, aso, ibon, at isda.", "scene": 0}, {"english": "A cat has whiskers. A dog can bark. A bird has feathers. A fish lives in water. Say each animal name slowly.", "filipino": "May bigote ang pusa. Maaaring tumahol ang aso. May balahibo ang ibon. Nakatira sa tubig ang isda. Dahan-dahang sabihin ang pangalan ng bawat hayop.", "scene": 0}, {"english": "Read: The bird is in the tree. Bird names the animal. Tree names the place where the bird is resting. Point to an animal in the picture and name it.", "filipino": "Basahin: Nasa puno ang ibon. Ibon ang ngalan ng hayop. Puno ang ngalan ng bagay na pinagpapahingahan nito. Ituro ang isang hayop sa larawan at pangalanan ito.", "scene": 0}, {"english": "Try it: Say a sentence about a cat or a dog. Start with The cat or The dog. Then tell what your animal does. You are ready for the animal quiz and word game!", "filipino": "Subukan: Magsabi ng pangungusap tungkol sa pusa o aso. Magsimula sa Ang pusa o Ang aso. Pagkatapos, sabihin ang ginagawa nito. Handa ka na para sa pagsusulit at laro!", "scene": 0}]}, "status": "published", "version": 1}, {"id": "f6c14311-3bad-52fa-b10e-fd13af704a4d", "owner_id": null, "kind": "quiz", "title": "Grade 1: Animal friends — Quiz", "grade_level": 1, "learning_level": "beginner", "summary": "Six questions: vocabulary and applying the lesson. Tap A, B, C, or D.", "source_label": "LinguaKids grade pathways · original supplemental enrichment v3", "body": {"cover_scene": 0, "unit_title": "Animal friends", "questions": [{"id": "98d96f83-25f4-5a43-83ec-6d4410099768", "prompt": "Which Filipino word or phrase means \"cat\"?", "options": [{"id": "915c8c3b-dc28-59b9-8498-ac3c1a350fa3", "text": "aso"}, {"id": "165633c3-7703-5c79-b51d-413873180f92", "text": "ibon"}, {"id": "ee68b3ff-b2e5-511c-96df-6d52c51a449e", "text": "isda"}, {"id": "6b96c4d2-2a7e-5dce-bff4-5ff61dab2937", "text": "pusa"}]}, {"id": "722df382-26e5-5e5e-b66e-7022286875b1", "prompt": "Which Filipino word or phrase means \"dog\"?", "options": [{"id": "1872d511-a4b4-51d9-83a9-c2e2e3b58d53", "text": "ibon"}, {"id": "1fe1f7aa-6e98-5f0e-8030-25083d64c32d", "text": "isda"}, {"id": "26e912f3-553a-548e-8d83-9f15bd754578", "text": "aso"}, {"id": "cc0c2ade-b5a6-5d48-ab5f-2273e330e6b3", "text": "pusa"}]}, {"id": "8e6cc91a-6c15-56b5-a5fe-1f9177017729", "prompt": "Which Filipino word or phrase means \"bird\"?", "options": [{"id": "0de4b5f1-444e-58ac-a0f6-083f747a5bf3", "text": "isda"}, {"id": "6f9bcaa3-d4dc-505b-ac47-df53f90fb780", "text": "ibon"}, {"id": "53822fb7-97d4-57c8-a4a2-da4a9507fe84", "text": "pusa"}, {"id": "5f3c85f4-7a1b-54b5-b2d7-ee60b554b43a", "text": "aso"}]}, {"id": "fca140bd-532b-5b47-92a4-384891f90075", "prompt": "Which Filipino word or phrase means \"fish\"?", "options": [{"id": "a2ce1deb-eb61-5f4c-8552-2a1c86623956", "text": "isda"}, {"id": "26018e50-970c-5bc6-ba38-4bfc18bdd193", "text": "pusa"}, {"id": "ece2a2ce-f3ab-5ea7-a169-b493cf14fd91", "text": "aso"}, {"id": "234f8d8a-ba41-5858-b1b5-b317724ae426", "text": "ibon"}]}, {"id": "af468444-40be-51c7-83d8-342802c8aeee", "prompt": "Which word names an animal?", "options": [{"id": "ad7734ff-5ad2-5e46-9938-3685a0c07ad5", "text": "jump"}, {"id": "e4c8933a-9406-585b-8cc1-af5560aebb6e", "text": "blue"}, {"id": "89355dcd-715a-5781-91a6-e851534d19ec", "text": "kind"}, {"id": "0f940711-db98-5f31-be7a-d4fa29190b4b", "text": "cat"}]}, {"id": "d2a199d4-3d9e-5115-839c-bbfd6b906caa", "prompt": "Which animal has feathers?", "options": [{"id": "16ff1654-58a0-50af-9ad9-f578f3206847", "text": "dog"}, {"id": "ee8ac377-a125-5176-9d92-d053184a9304", "text": "cat"}, {"id": "55af8ba2-6397-5826-9cbf-245e19900883", "text": "bird"}, {"id": "61956f03-2eb5-5dda-a7fb-580a7fb70b86", "text": "fish"}]}]}, "status": "published", "version": 1}, {"id": "b53542c4-382e-5180-bcd6-c71cade8112d", "owner_id": null, "kind": "game", "title": "Grade 1: Animal friends — Word game", "grade_level": 1, "learning_level": "beginner", "summary": "Match four lesson words with their Filipino meanings.", "source_label": "LinguaKids grade pathways · original supplemental enrichment v3", "body": {"cover_scene": 0, "unit_title": "Animal friends", "pairs": [{"en": "cat", "fil": "pusa"}, {"en": "dog", "fil": "aso"}, {"en": "bird", "fil": "ibon"}, {"en": "fish", "fil": "isda"}]}, "status": "published", "version": 1}, {"id": "7468ae9b-f286-5bfd-bb22-9f5dd5e69524", "owner_id": null, "kind": "lesson", "title": "Grade 1: Colors in the garden", "grade_level": 1, "learning_level": "beginner", "summary": "Four bilingual learning pages with examples and a practice task.", "source_label": "LinguaKids grade pathways · original supplemental enrichment v3", "body": {"cover_scene": 8, "unit_title": "Colors in the garden", "pages": [{"english": "Color words tell us what something looks like. Red, blue, yellow, and green are color words. Look for these colors in the garden picture.", "filipino": "Sinasabi ng mga salitang pangkulay ang hitsura ng isang bagay. Pula, asul, dilaw, at berde ang ilan sa mga kulay. Hanapin ang mga kulay na ito sa larawan ng hardin.", "scene": 8}, {"english": "A ripe tomato can be red. The clear daytime sky can look blue. A sunflower can be yellow. A healthy leaf is often green.", "filipino": "Maaaring pula ang hinog na kamatis. Maaaring asul ang maaliwalas na langit sa araw. Maaaring dilaw ang mirasol. Madalas ay berde ang malusog na dahon.", "scene": 8}, {"english": "Read: Milo sees a yellow flower. Yellow describes the flower. We can use a color word before a thing: red ball, blue bag, green leaf.", "filipino": "Basahin: Nakakita si Milo ng dilaw na bulaklak. Inilalarawan ng dilaw ang bulaklak. Maaari tayong gumamit ng kulay bago ang isang bagay: pulang bola, asul na bag, berdeng dahon.", "scene": 8}, {"english": "Try it: Find three safe things near you. Name each thing and its color. Colors help us describe what we see. Now practice the four garden colors.", "filipino": "Subukan: Humanap ng tatlong ligtas na bagay sa paligid. Sabihin ang ngalan at kulay ng bawat isa. Nakakatulong ang kulay upang ilarawan ang nakikita. Magsanay sa apat na kulay ng hardin.", "scene": 8}]}, "status": "published", "version": 1}, {"id": "f82bee1d-dfcf-51c0-9cc5-e6006429024e", "owner_id": null, "kind": "quiz", "title": "Grade 1: Colors in the garden — Quiz", "grade_level": 1, "learning_level": "beginner", "summary": "Six questions: vocabulary and applying the lesson. Tap A, B, C, or D.", "source_label": "LinguaKids grade pathways · original supplemental enrichment v3", "body": {"cover_scene": 8, "unit_title": "Colors in the garden", "questions": [{"id": "9ff312d9-688e-5003-9e10-24724170507a", "prompt": "Which Filipino word or phrase means \"red\"?", "options": [{"id": "6943d6c6-3dc1-5f94-a538-01c1883ecb03", "text": "asul"}, {"id": "ca6cfbce-3e2a-56c1-9258-a471699b6a25", "text": "dilaw"}, {"id": "5a2bfd61-ef8d-58ec-a313-5e37ed9f329c", "text": "berde"}, {"id": "44a685bf-7b89-5df7-a12d-280bff58bb48", "text": "pula"}]}, {"id": "d5450251-358b-57e8-95d5-de3ebc7a54df", "prompt": "Which Filipino word or phrase means \"blue\"?", "options": [{"id": "dd2e301e-f521-5b35-a8b2-b3c29ec86f40", "text": "dilaw"}, {"id": "62676efe-446c-55e6-a778-07b8ff228b93", "text": "berde"}, {"id": "91938ed0-fd3a-5f65-958d-bd57fd272c06", "text": "asul"}, {"id": "28bb732e-a5e3-5214-af7a-c312994ce10d", "text": "pula"}]}, {"id": "cb21a38b-d676-5e5b-be50-6108d455db07", "prompt": "Which Filipino word or phrase means \"yellow\"?", "options": [{"id": "25812568-f9b2-53f2-9a20-129105764808", "text": "berde"}, {"id": "52000eac-3214-5ff2-983c-49b6b3fbcefe", "text": "dilaw"}, {"id": "8def3318-fc1d-57dc-b9de-7da0b9758007", "text": "pula"}, {"id": "e051f53a-0e44-56f0-b53d-5b40495ae054", "text": "asul"}]}, {"id": "e6b7057d-491c-568e-ba9e-066e68f83da4", "prompt": "Which Filipino word or phrase means \"green\"?", "options": [{"id": "e32e372d-8782-5516-bda2-7ea22dcc781a", "text": "berde"}, {"id": "07f56165-9f66-5f41-b5e9-5f6bf6473716", "text": "pula"}, {"id": "846f7576-7eb0-583e-8193-46b9e3fb629c", "text": "asul"}, {"id": "0d2d56d8-d81e-550f-b41f-48bd242fbaff", "text": "dilaw"}]}, {"id": "309a01af-1c21-5f9c-acc5-1d92d92a5162", "prompt": "In yellow flower, which word tells the color?", "options": [{"id": "0984c8df-fbb3-528c-b82a-626d9f980185", "text": "flower"}, {"id": "6098d3bf-2888-5921-9fe4-14823baba1dd", "text": "garden"}, {"id": "efcb324a-69da-53b6-a96a-1e0d5a6a06ae", "text": "Milo"}, {"id": "42139cda-4d0b-5db3-a955-0de661592177", "text": "yellow"}]}, {"id": "e5b7e143-6754-53f1-82de-f0650470f318", "prompt": "Which phrase includes a color word?", "options": [{"id": "262ad4ac-b044-5887-b1c7-2539454c34e3", "text": "happy child"}, {"id": "a1f50c75-c200-50fb-95f9-628e33534b1f", "text": "three books"}, {"id": "c2a41b40-2505-502c-9979-0bd1d6549967", "text": "green leaf"}, {"id": "a1b46e71-3cf7-534d-9c6b-849967be8314", "text": "small rabbit"}]}]}, "status": "published", "version": 1}, {"id": "66857459-ae83-5c38-a439-da75bab24c3f", "owner_id": null, "kind": "game", "title": "Grade 1: Colors in the garden — Word game", "grade_level": 1, "learning_level": "beginner", "summary": "Match four lesson words with their Filipino meanings.", "source_label": "LinguaKids grade pathways · original supplemental enrichment v3", "body": {"cover_scene": 8, "unit_title": "Colors in the garden", "pairs": [{"en": "red", "fil": "pula"}, {"en": "blue", "fil": "asul"}, {"en": "yellow", "fil": "dilaw"}, {"en": "green", "fil": "berde"}]}, "status": "published", "version": 1}, {"id": "f0d05889-da45-5e6d-aa3e-132ee98530dc", "owner_id": null, "kind": "lesson", "title": "Grade 1: Kind words every day", "grade_level": 1, "learning_level": "beginner", "summary": "Four bilingual learning pages with examples and a practice task.", "source_label": "LinguaKids grade pathways · original supplemental enrichment v3", "body": {"cover_scene": 12, "unit_title": "Kind words every day", "pages": [{"english": "Kind words help people feel welcome. Say hello when you greet someone. Say please when asking politely. Say thank you when someone helps you.", "filipino": "Nakakatulong ang magagalang na salita upang maging magaan ang pakikitungo. Magsabi ng kumusta sa pagbati. Gumamit ng pakiusap kapag may hinihiling. Magsabi ng salamat kapag may tumulong.", "scene": 12}, {"english": "If you bump into someone by accident, say sorry and check that they are okay. Words are kind when our actions are kind too.", "filipino": "Kapag hindi sinasadyang nakabangga, humingi ng paumanhin at tiyaking ayos ang nabangga. Nagiging magalang ang salita kapag magalang din ang kilos.", "scene": 12}, {"english": "Read: May I borrow your book, please? Luna gives Finn a book. Finn says, Thank you! Finn asks before borrowing and thanks his friend afterward.", "filipino": "Basahin: Maaari ko bang hiramin ang aklat mo? Ibinigay ni Luna kay Finn ang aklat. Sinabi ni Finn, Salamat! Nagpaalam si Finn bago humiram at nagpasalamat pagkatapos.", "scene": 12}, {"english": "Try it: Practice greeting a friend, asking for a turn, and thanking a helper. Use a calm voice. You can practice these words with a trusted adult.", "filipino": "Subukan: Magsanay sa pagbati, paghingi ng pagkakataon, at pagpapasalamat. Gumamit ng mahinahong boses. Maaari kang magsanay kasama ang pinagkakatiwalaang nakatatanda.", "scene": 12}]}, "status": "published", "version": 1}, {"id": "b8cccf45-d800-5908-b67f-970fcd708421", "owner_id": null, "kind": "quiz", "title": "Grade 1: Kind words every day — Quiz", "grade_level": 1, "learning_level": "beginner", "summary": "Six questions: vocabulary and applying the lesson. Tap A, B, C, or D.", "source_label": "LinguaKids grade pathways · original supplemental enrichment v3", "body": {"cover_scene": 12, "unit_title": "Kind words every day", "questions": [{"id": "414d1f9a-84ab-557a-98b5-c73ed3695619", "prompt": "Which Filipino word or phrase means \"hello\"?", "options": [{"id": "00d88eca-4fb2-501b-942c-56376e3a3e14", "text": "pakiusap"}, {"id": "4d772afd-eb90-5cbf-84ac-131e1f2668c2", "text": "salamat"}, {"id": "4f32e4a0-839c-5130-a03a-785d1974fca2", "text": "paumanhin"}, {"id": "789d35be-5819-5a60-b8f0-553dfe14ff94", "text": "kumusta"}]}, {"id": "5ae2a3bf-1948-5be5-bcbb-64542e70594e", "prompt": "Which Filipino word or phrase means \"please\"?", "options": [{"id": "fc2f83d7-914a-5cdd-9093-ef42b776ab53", "text": "salamat"}, {"id": "2e2ddcbb-e8a5-5b9a-acc2-c58a66e2e486", "text": "paumanhin"}, {"id": "72744891-bab2-5f6e-9c05-e94e48f0e4bd", "text": "pakiusap"}, {"id": "5d3e07b3-c34c-5ce8-a8bf-2a6e3630202f", "text": "kumusta"}]}, {"id": "3aef308c-15c5-54d0-b91b-f8be10371838", "prompt": "Which Filipino word or phrase means \"thank you\"?", "options": [{"id": "f15e25b9-b07b-5ba1-9999-c98b75fc7084", "text": "paumanhin"}, {"id": "c816824d-2d51-51ab-a9cf-e5e79f356767", "text": "salamat"}, {"id": "f68e7385-8aef-52b7-9120-87b76a0a1ad3", "text": "kumusta"}, {"id": "d623a770-1855-5201-84ca-bdcfa8d9fcc0", "text": "pakiusap"}]}, {"id": "b5f08d34-846c-58b1-b526-8617f9db345d", "prompt": "Which Filipino word or phrase means \"sorry\"?", "options": [{"id": "c3236810-ebbc-5f2f-8d6f-1088174f31c0", "text": "paumanhin"}, {"id": "c43b97dc-7c08-5287-84ad-0a9e2e1d6d87", "text": "kumusta"}, {"id": "09151609-4d6d-5fe2-8f7f-017b85e2afcf", "text": "pakiusap"}, {"id": "2704dca9-fb4f-5464-867b-215b84fd4bb6", "text": "salamat"}]}, {"id": "72750259-1439-5549-92e6-05e8e96a96b0", "prompt": "A friend shares a pencil. What can you say?", "options": [{"id": "ca2e66d4-a5aa-5917-b672-74ae44d0b390", "text": "Go away!"}, {"id": "e491fc38-baa6-508c-83e4-8a29c07d8a6a", "text": "That is mine!"}, {"id": "7cd7d043-6060-5061-908b-cc2e9ef1a96f", "text": "Hurry up!"}, {"id": "a59ff248-3e09-5a84-a4a2-0258b3ba8224", "text": "Thank you!"}]}, {"id": "7a220247-70da-55b1-88d7-3c724ed87e40", "prompt": "What should you do before borrowing a book?", "options": [{"id": "7cd799b3-34c4-5583-a0f8-3e77f989f733", "text": "Take it without asking."}, {"id": "6322e67e-e06a-55a0-a5b7-fd563327eaab", "text": "Tear a page."}, {"id": "26a23b2e-a011-5f69-bbd1-e2168428d8a2", "text": "Ask politely."}, {"id": "0ed8d518-74ec-5c76-81b5-160efb67fad2", "text": "Hide it."}]}]}, "status": "published", "version": 1}, {"id": "335cb1ff-e898-5b51-9dba-84be2e8dd748", "owner_id": null, "kind": "game", "title": "Grade 1: Kind words every day — Word game", "grade_level": 1, "learning_level": "beginner", "summary": "Match four lesson words with their Filipino meanings.", "source_label": "LinguaKids grade pathways · original supplemental enrichment v3", "body": {"cover_scene": 12, "unit_title": "Kind words every day", "pairs": [{"en": "hello", "fil": "kumusta"}, {"en": "please", "fil": "pakiusap"}, {"en": "thank you", "fil": "salamat"}, {"en": "sorry", "fil": "paumanhin"}]}, "status": "published", "version": 1}, {"id": "4264e7e1-2fe8-5ade-a0dc-7caa363f2df6", "owner_id": null, "kind": "lesson", "title": "Grade 2: Action words on the playground", "grade_level": 2, "learning_level": "beginner", "summary": "Four bilingual learning pages with examples and a practice task.", "source_label": "LinguaKids grade pathways · original supplemental enrichment v3", "body": {"cover_scene": 0, "unit_title": "Action words on the playground", "pages": [{"english": "An action word, or verb, tells what someone does. Run, jump, read, and write are action words. Look for the action in each sentence.", "filipino": "Sinasabi ng pandiwa ang kilos na ginagawa. Ang tumakbo, tumalon, bumasa, at sumulat ay mga salitang kilos. Hanapin ang kilos sa bawat pangungusap.", "scene": 0}, {"english": "Read: The rabbit jumps. The owl reads. Jumps and reads tell what the animals do. In a sentence, an action word works with the person or animal doing it.", "filipino": "Basahin: Tumatalon ang kuneho. Bumabasa ang kuwago. Sinasabi ng tumatalon at bumabasa ang kilos ng mga hayop. Kasama ng pandiwa ang gumagawa ng kilos sa pangungusap.", "scene": 0}, {"english": "The children write in their notebooks. Who does the action? The children. What do they do? They write. Notice that notebooks names a thing, while write names an action.", "filipino": "Sumusulat ang mga bata sa kanilang kuwaderno. Sino ang gumagawa? Ang mga bata. Ano ang ginagawa nila? Sumusulat sila. Bagay ang kuwaderno, samantalang kilos ang sumulat.", "scene": 0}, {"english": "Try it: Tell two actions you can do safely. Make one sentence for each action. Then find action words in the quiz. You do not need to act out running indoors.", "filipino": "Subukan: Magbanggit ng dalawang ligtas na kilos na kaya mong gawin. Gumawa ng pangungusap para sa bawat isa. Hanapin ang mga pandiwa sa pagsusulit. Hindi kailangang tumakbo sa loob ng bahay.", "scene": 0}]}, "status": "published", "version": 1}, {"id": "1d6814da-1b82-5a99-8ece-3edd267ea621", "owner_id": null, "kind": "quiz", "title": "Grade 2: Action words on the playground — Quiz", "grade_level": 2, "learning_level": "beginner", "summary": "Six questions: vocabulary and applying the lesson. Tap A, B, C, or D.", "source_label": "LinguaKids grade pathways · original supplemental enrichment v3", "body": {"cover_scene": 0, "unit_title": "Action words on the playground", "questions": [{"id": "cb66e439-ceca-5954-9774-23366922e6aa", "prompt": "Which Filipino word or phrase means \"run\"?", "options": [{"id": "05835809-9922-50f5-9740-2c72060d6891", "text": "bumasa"}, {"id": "a4740c50-de2f-5d69-8fe8-c90c7c80506a", "text": "sumulat"}, {"id": "236030d8-5235-5c93-aa72-4fe88591f2c6", "text": "tumakbo"}, {"id": "ebafeaa8-ccd8-5cd1-8191-16e245178bde", "text": "tumalon"}]}, {"id": "43505caf-ae3f-53cd-86d8-278dc901daa0", "prompt": "Which Filipino word or phrase means \"jump\"?", "options": [{"id": "41f03cdb-0917-5454-a1e9-734652d5e2d1", "text": "sumulat"}, {"id": "707a8ea5-01f2-5324-88a0-3577b0ad5639", "text": "tumalon"}, {"id": "76e02fab-3c6a-5558-83cf-9940f6b2426e", "text": "tumakbo"}, {"id": "76fee77a-c2ec-51b6-a950-584e2f8422f3", "text": "bumasa"}]}, {"id": "73ede753-6991-50b6-8540-75ea9a657877", "prompt": "Which Filipino word or phrase means \"read\"?", "options": [{"id": "ae583b26-7005-5fdd-9bd5-64988d3f522e", "text": "bumasa"}, {"id": "77095f72-5dac-570d-9b3b-f3a1978eef5e", "text": "tumakbo"}, {"id": "09d2c469-e4dd-5f20-863c-e846193895e0", "text": "tumalon"}, {"id": "679f2587-8963-535b-aef6-8c831b3a16ba", "text": "sumulat"}]}, {"id": "24f7edae-0a5b-598a-96b3-bdb82170fffd", "prompt": "Which Filipino word or phrase means \"write\"?", "options": [{"id": "c800d91d-b734-5e2c-a341-cb3f053c1081", "text": "tumakbo"}, {"id": "0a9865e9-acd8-58c3-b7b8-e748b278d1b4", "text": "tumalon"}, {"id": "77ce3975-3def-507f-87da-7159c59a6d40", "text": "bumasa"}, {"id": "db27438d-ae9a-5da3-8ca7-961a9b4e2ce2", "text": "sumulat"}]}, {"id": "07225348-07b0-5fee-9d2c-24d9d9b2be4a", "prompt": "In The rabbit jumps, which word is an action?", "options": [{"id": "0d2b2bb4-c4d2-59ca-8dc5-64c3cbc25234", "text": "the"}, {"id": "80109805-7725-59ee-900b-ef519977d0ab", "text": "animal"}, {"id": "c69ebd85-55aa-5aae-aa3d-83ab1ec11cf1", "text": "jumps"}, {"id": "42616d52-79ac-5976-a5b6-8bfeeb310dfd", "text": "rabbit"}]}, {"id": "f503ff96-b9a8-5d4f-91be-13031ca6d188", "prompt": "Which sentence tells an action?", "options": [{"id": "24ca5af0-1446-5ec5-bb5c-5bdaed898e8b", "text": "The sky is clear."}, {"id": "83f7db04-3eb7-57b9-af65-0a3144e2a16c", "text": "The owl reads a book."}, {"id": "4afb4cab-8270-568d-8a7a-24623570acab", "text": "The book is blue."}, {"id": "d80e16bf-6c0d-5529-a530-cec013040cc3", "text": "The owl is small."}]}]}, "status": "published", "version": 1}, {"id": "0a7edc47-e1da-5928-914d-ff9499d65fe2", "owner_id": null, "kind": "game", "title": "Grade 2: Action words on the playground — Word game", "grade_level": 2, "learning_level": "beginner", "summary": "Match four lesson words with their Filipino meanings.", "source_label": "LinguaKids grade pathways · original supplemental enrichment v3", "body": {"cover_scene": 0, "unit_title": "Action words on the playground", "pairs": [{"en": "run", "fil": "tumakbo"}, {"en": "jump", "fil": "tumalon"}, {"en": "read", "fil": "bumasa"}, {"en": "write", "fil": "sumulat"}]}, "status": "published", "version": 1}, {"id": "c716e9e1-f66c-51c0-9e90-51aeb67b2c7a", "owner_id": null, "kind": "lesson", "title": "Grade 2: Where is the little turtle?", "grade_level": 2, "learning_level": "beginner", "summary": "Four bilingual learning pages with examples and a practice task.", "source_label": "LinguaKids grade pathways · original supplemental enrichment v3", "body": {"cover_scene": 1, "unit_title": "Where is the little turtle?", "pages": [{"english": "Position words tell where something is. In, on, under, and beside help us describe a place. Imagine a turtle near a toy box.", "filipino": "Sinasabi ng mga salitang panlunan kung nasaan ang isang bagay. Sa loob, sa ibabaw, sa ilalim, at sa tabi ang ilang halimbawa. Isipin ang pagong na malapit sa kahon ng laruan.", "scene": 1}, {"english": "A ball in the box is inside it. A book on the box rests on top. A cat under the table is below it. A bag beside the chair is next to it.", "filipino": "Nasa loob ng kahon ang bolang nakalagay dito. Nasa ibabaw ang aklat na nakapatong sa kahon. Nasa ilalim ng mesa ang pusang nasa ibaba nito. Nasa tabi ng upuan ang bag na katabi nito.", "scene": 1}, {"english": "Read: Tali rests under a tree. Under tells where Tali rests. If Tali moves beside the tree, the position changes even though the tree stays in the same place.", "filipino": "Basahin: Nagpapahinga si Tali sa ilalim ng puno. Sinasabi ng sa ilalim kung nasaan si Tali. Kapag lumipat siya sa tabi ng puno, nagbabago ang kaniyang puwesto kahit hindi gumalaw ang puno.", "scene": 1}, {"english": "Try it: Put a pencil beside a book. Tell where the pencil is. Move it onto the book and describe the new position. Ask an adult before moving large objects.", "filipino": "Subukan: Ilagay ang lapis sa tabi ng aklat. Sabihin kung nasaan ito. Ipatong ito sa aklat at ilarawan ang bagong puwesto. Magpaalam sa nakatatanda bago maglipat ng mabibigat na bagay.", "scene": 1}]}, "status": "published", "version": 1}, {"id": "ccb2509e-46a3-5f7f-8812-e966c6041cd6", "owner_id": null, "kind": "quiz", "title": "Grade 2: Where is the little turtle? — Quiz", "grade_level": 2, "learning_level": "beginner", "summary": "Six questions: vocabulary and applying the lesson. Tap A, B, C, or D.", "source_label": "LinguaKids grade pathways · original supplemental enrichment v3", "body": {"cover_scene": 1, "unit_title": "Where is the little turtle?", "questions": [{"id": "35bbb2d9-9a7f-5c80-8726-99a3975f4617", "prompt": "Which Filipino word or phrase means \"in\"?", "options": [{"id": "a9198704-39c3-5c5e-8edd-8992c4b441d1", "text": "sa ilalim"}, {"id": "3c2902d8-3a92-53fa-a8ae-e7dcd4b8ad81", "text": "sa tabi"}, {"id": "c2458d62-bbb4-580c-9092-184c001bbe37", "text": "sa loob"}, {"id": "4a4bdee6-a604-52b7-b7b3-1d359968bb66", "text": "sa ibabaw"}]}, {"id": "92036c26-400c-5435-aeeb-48e16727a37e", "prompt": "Which Filipino word or phrase means \"on\"?", "options": [{"id": "93902ff5-8103-5a7d-867d-3a7f2b2a8758", "text": "sa tabi"}, {"id": "7f698441-2f02-5c13-b570-e956495fa56d", "text": "sa ibabaw"}, {"id": "fc057d46-ddc6-558a-a647-abc87b5e07a3", "text": "sa loob"}, {"id": "01810cf7-8971-5838-97a3-fa354f4eae31", "text": "sa ilalim"}]}, {"id": "9e12f6f5-295e-55f0-895d-7c18361af62b", "prompt": "Which Filipino word or phrase means \"under\"?", "options": [{"id": "27252744-8186-5cc9-9caf-f13be38c9bf5", "text": "sa ilalim"}, {"id": "e3e6fb4f-f2ac-574e-b8b5-09ad1fe2a950", "text": "sa loob"}, {"id": "098112f4-ef41-528d-b243-244c33d30f54", "text": "sa ibabaw"}, {"id": "55c861c7-5259-5530-bc43-e566d5500bdc", "text": "sa tabi"}]}, {"id": "2fc766fc-6c0f-5aa7-874f-c5567f3ffc11", "prompt": "Which Filipino word or phrase means \"beside\"?", "options": [{"id": "51dce378-50a8-5f50-8d40-26681dae4192", "text": "sa loob"}, {"id": "78045d06-6c35-5a4c-b7fc-ec401f39880f", "text": "sa ibabaw"}, {"id": "f0307507-2092-5e0a-8dca-2f0138d65eb2", "text": "sa ilalim"}, {"id": "98a53ea8-5094-5dc4-8b00-c3bc38b25511", "text": "sa tabi"}]}, {"id": "b9c3d302-d003-5a1f-95ef-c56d15ed76fe", "prompt": "A bag is next to a chair. Which word describes its position?", "options": [{"id": "fe5b2398-8ea3-5cf3-a3d3-b6b7af26f6ac", "text": "inside"}, {"id": "21840ca5-638a-5e0d-a9b2-333812b70527", "text": "above"}, {"id": "17094b1d-093c-5958-8e2e-f4aae82757ed", "text": "beside"}, {"id": "3df8348a-da4a-57c9-a796-7699e4a255a2", "text": "under"}]}, {"id": "8343e9de-6f8c-5fc9-b988-46fe5b94585e", "prompt": "In The cat sleeps under the table, where is the cat?", "options": [{"id": "736bccbb-b963-5263-961c-119ca7895843", "text": "beside a tree"}, {"id": "98dfe8d1-fbb0-5a91-86b0-d0d1895be6b6", "text": "below the table"}, {"id": "13a1d69f-6509-52a1-baf5-cd9ec5bab4d7", "text": "on top of the table"}, {"id": "4d331c61-e8cf-522d-b1b2-1926dc7f4a8c", "text": "inside a box"}]}]}, "status": "published", "version": 1}, {"id": "ae8a49dc-a125-5dba-99aa-2b3f8f4d42b4", "owner_id": null, "kind": "game", "title": "Grade 2: Where is the little turtle? — Word game", "grade_level": 2, "learning_level": "beginner", "summary": "Match four lesson words with their Filipino meanings.", "source_label": "LinguaKids grade pathways · original supplemental enrichment v3", "body": {"cover_scene": 1, "unit_title": "Where is the little turtle?", "pairs": [{"en": "in", "fil": "sa loob"}, {"en": "on", "fil": "sa ibabaw"}, {"en": "under", "fil": "sa ilalim"}, {"en": "beside", "fil": "sa tabi"}]}, "status": "published", "version": 1}, {"id": "ca5e6559-9a4f-569a-84e6-76947263b758", "owner_id": null, "kind": "lesson", "title": "Grade 2: Complete sentences with Luna", "grade_level": 2, "learning_level": "beginner", "summary": "Four bilingual learning pages with examples and a practice task.", "source_label": "LinguaKids grade pathways · original supplemental enrichment v3", "body": {"cover_scene": 12, "unit_title": "Complete sentences with Luna", "pages": [{"english": "A complete sentence shares a complete thought. It tells who or what we are talking about and says something about that person or thing.", "filipino": "Nagpapahayag ng buong diwa ang pangungusap. Sinasabi nito kung sino o ano ang pinag-uusapan at may sinasabi tungkol dito.", "scene": 12}, {"english": "Read: Luna reads a book. This is a complete thought. Luna tells who. Reads a book tells what she does. A sentence begins with a capital letter.", "filipino": "Basahin: Bumabasa ng aklat si Luna. Buo ang diwa nito. Si Luna ang pinag-uusapan. Bumabasa ng aklat ang sinasabi tungkol sa kaniya. Nagsisimula ang pangungusap sa malaking titik.", "scene": 12}, {"english": "A statement usually ends with a period. A question ends with a question mark. A word group such as the little owl does not yet tell a complete thought.", "filipino": "Karaniwang nagtatapos sa tuldok ang pasalaysay. Nagtatapos sa tandang pananong ang tanong. Hindi pa buo ang diwa ng pangkat ng salitang ang munting kuwago.", "scene": 12}, {"english": "Try it: Finish this thought: The rabbit ___. You might say The rabbit jumps. Check the capital letter and ending mark. Read your sentence aloud.", "filipino": "Subukan: Kumpletuhin: Ang kuneho ay ___. Maaaring sabihin, Ang kuneho ay tumatalon. Suriin ang malaking titik at bantas sa hulihan. Basahin nang malakas ang pangungusap.", "scene": 12}]}, "status": "published", "version": 1}, {"id": "a8825596-d276-5a18-8d07-a25eb087f792", "owner_id": null, "kind": "quiz", "title": "Grade 2: Complete sentences with Luna — Quiz", "grade_level": 2, "learning_level": "beginner", "summary": "Six questions: vocabulary and applying the lesson. Tap A, B, C, or D.", "source_label": "LinguaKids grade pathways · original supplemental enrichment v3", "body": {"cover_scene": 12, "unit_title": "Complete sentences with Luna", "questions": [{"id": "71367802-f075-5138-a602-a1ffe1c87fc5", "prompt": "Which Filipino word or phrase means \"sentence\"?", "options": [{"id": "651b3cf6-ad0a-5e50-8a14-109eda717cf9", "text": "tuldok"}, {"id": "d0cc140e-2d68-5cca-847f-7ed240d9561f", "text": "tanong"}, {"id": "56b80e5f-fad8-5ce9-ac82-f43c87a1e7e3", "text": "pangungusap"}, {"id": "87ff0344-6f08-5c61-adc4-70e0826f0d8d", "text": "salita"}]}, {"id": "33541a16-8c61-5a12-937d-977656d8036d", "prompt": "Which Filipino word or phrase means \"word\"?", "options": [{"id": "e43d876c-2e83-5132-b0b9-46afc3ba3679", "text": "tanong"}, {"id": "1295b72a-e9ba-5284-83fa-bafb5861a995", "text": "salita"}, {"id": "1507b51d-e2a0-5901-9e20-7917481d4dc8", "text": "pangungusap"}, {"id": "f17ef67b-32e6-5e2d-9336-fee0b80c074d", "text": "tuldok"}]}, {"id": "f5128dd6-9b7b-506c-92db-9c2d0517c71a", "prompt": "Which Filipino word or phrase means \"period\"?", "options": [{"id": "125490c2-435d-5640-8084-5527fbc3fd0b", "text": "tuldok"}, {"id": "951d30a4-78e4-5fcb-9678-1876f12909c8", "text": "pangungusap"}, {"id": "3d30ea90-fc31-5b11-ab6f-6310d5678946", "text": "salita"}, {"id": "121e99a0-c327-5aa9-ba07-916ee33d3f3c", "text": "tanong"}]}, {"id": "b22ea147-4311-5ca8-a49f-58fe61c69d8a", "prompt": "Which Filipino word or phrase means \"question\"?", "options": [{"id": "5c23bbcf-bad3-5f0e-b5f9-64f6d5d0e64f", "text": "pangungusap"}, {"id": "bff4254f-8176-58da-a6dd-d4ba23720cf5", "text": "salita"}, {"id": "de42b18a-6005-5817-9f4d-cdf7c80899d4", "text": "tuldok"}, {"id": "51cf7e73-d54e-5d6b-b010-d6dfba0e20ea", "text": "tanong"}]}, {"id": "fd325643-e363-5662-8768-ff5ba1e6a8a5", "prompt": "Which is a complete sentence?", "options": [{"id": "b81f2165-7ccb-5314-9e96-c3a48bdfca40", "text": "A purple book"}, {"id": "5a9c1fc8-cebd-5a4b-819c-fa8031a61614", "text": "Under the tree"}, {"id": "90220d85-92cf-50b0-a14e-02fa21b859c1", "text": "The owl reads."}, {"id": "2490cc6e-ed6c-5040-ad32-471f9e7eb87f", "text": "The little owl"}]}, {"id": "19777e99-1936-5a55-a811-b8ac9bfac0ae", "prompt": "Which mark ends a direct question?", "options": [{"id": "1892b3a1-9536-5e29-9e33-65d043fc6a06", "text": "apostrophe"}, {"id": "b5a861f2-ad5b-532a-b538-fff9e7bf0da5", "text": "question mark"}, {"id": "b2e4a027-b376-586a-a615-18069f9180a1", "text": "comma"}, {"id": "443f681b-f902-5940-b80d-b664102c27e8", "text": "period only"}]}]}, "status": "published", "version": 1}, {"id": "8868da75-1e7f-5eb9-877d-46aff7b77084", "owner_id": null, "kind": "game", "title": "Grade 2: Complete sentences with Luna — Word game", "grade_level": 2, "learning_level": "beginner", "summary": "Match four lesson words with their Filipino meanings.", "source_label": "LinguaKids grade pathways · original supplemental enrichment v3", "body": {"cover_scene": 12, "unit_title": "Complete sentences with Luna", "pairs": [{"en": "sentence", "fil": "pangungusap"}, {"en": "word", "fil": "salita"}, {"en": "period", "fil": "tuldok"}, {"en": "question", "fil": "tanong"}]}, "status": "published", "version": 1}, {"id": "c738518d-a9d7-529d-aae4-9991957f1314", "owner_id": null, "kind": "lesson", "title": "Grade 3: Describe our animal friends", "grade_level": 3, "learning_level": "developing", "summary": "Four bilingual learning pages with examples and a practice task.", "source_label": "LinguaKids grade pathways · original supplemental enrichment v3", "body": {"cover_scene": 8, "unit_title": "Describe our animal friends", "pages": [{"english": "An adjective describes a noun. It can tell size, color, shape, or a quality. In a gentle turtle, gentle describes turtle.", "filipino": "Inilalarawan ng pang-uri ang pangngalan. Maaari nitong sabihin ang laki, kulay, hugis, o katangian. Sa mahinahong pagong, inilalarawan ng mahinahon ang pagong.", "scene": 8}, {"english": "Read: The small rabbit carries a bright basket. Small describes rabbit. Bright describes basket. Describing words help a reader imagine a scene.", "filipino": "Basahin: May dalang matingkad na basket ang maliit na kuneho. Inilalarawan ng maliit ang kuneho. Inilalarawan ng matingkad ang basket. Nakakatulong ang pang-uri upang maisip ng mambabasa ang tagpo.", "scene": 8}, {"english": "A kind friend shares a turn. A brave helper asks an adult for help when needed. Kind and brave describe qualities rather than colors or sizes.", "filipino": "Nagbabahagi ng pagkakataon ang mabait na kaibigan. Humihingi ng tulong sa nakatatanda ang matapang na katulong kapag kailangan. Katangian ang inilalarawan ng mabait at matapang.", "scene": 8}, {"english": "Try it: Choose one animal. Describe it with two adjectives and use the words in a complete sentence. Be specific: a small green turtle is clearer than a nice thing.", "filipino": "Subukan: Pumili ng hayop. Ilarawan ito gamit ang dalawang pang-uri at gamitin sa buong pangungusap. Maging tiyak: mas malinaw ang maliit na berdeng pagong kaysa magandang bagay.", "scene": 8}]}, "status": "published", "version": 1}, {"id": "904e3514-e01f-5fc0-9cda-3c0148d25a83", "owner_id": null, "kind": "quiz", "title": "Grade 3: Describe our animal friends — Quiz", "grade_level": 3, "learning_level": "developing", "summary": "Six questions: vocabulary and applying the lesson. Tap A, B, C, or D.", "source_label": "LinguaKids grade pathways · original supplemental enrichment v3", "body": {"cover_scene": 8, "unit_title": "Describe our animal friends", "questions": [{"id": "cce6dad8-1b03-5e70-bd91-1fd8c83d3fd1", "prompt": "Which Filipino word or phrase means \"small\"?", "options": [{"id": "7ac105be-40f2-59df-beeb-4ea8fa93ff81", "text": "matapang"}, {"id": "83d0a811-75ce-54e3-bf60-bf16989d7147", "text": "maliit"}, {"id": "b9eec48f-02f0-5bd3-b32e-27a400d741ca", "text": "matingkad"}, {"id": "60e6580d-28ec-557c-aa24-81a01420c42f", "text": "mabait"}]}, {"id": "cb7003d1-f6ca-5f28-94b1-c5da0c61ee86", "prompt": "Which Filipino word or phrase means \"bright\"?", "options": [{"id": "fc6c272f-d83f-54e4-a960-2ff58d72a70e", "text": "matingkad"}, {"id": "d76fe675-07f5-5fe1-a551-38d6f08840de", "text": "maliit"}, {"id": "4ada2469-8cd9-53a9-8bd9-e74838ad28eb", "text": "mabait"}, {"id": "389af6bc-bdae-5bcc-86be-9dd0b9df6fac", "text": "matapang"}]}, {"id": "07ed9ad6-f960-5bfd-8fd3-206bf7f55724", "prompt": "Which Filipino word or phrase means \"kind\"?", "options": [{"id": "edc3986c-5530-5e06-9b74-ee1a6a135314", "text": "maliit"}, {"id": "706a201e-9c44-5ad9-96bf-15a7380132c8", "text": "matingkad"}, {"id": "b9bb2f52-ec8f-54da-84fe-ae6131a93b4d", "text": "matapang"}, {"id": "af984368-b442-5a25-96e0-74aa916764cf", "text": "mabait"}]}, {"id": "65196aba-bc77-5182-8369-621aece78ab1", "prompt": "Which Filipino word or phrase means \"brave\"?", "options": [{"id": "67873c4a-fcb1-5456-a745-5c791f9cefb7", "text": "matingkad"}, {"id": "b2046c3f-9fd6-57e1-859c-5960825a3f42", "text": "mabait"}, {"id": "0c83ae44-8e2a-5a36-a904-ae43ea9c9182", "text": "matapang"}, {"id": "aefec7be-5b43-5b1d-85a2-0fb00b5fa2bb", "text": "maliit"}]}, {"id": "638215be-1ebd-5b36-ab49-ea0a96dae80b", "prompt": "In a small green turtle, which words describe the turtle?", "options": [{"id": "692bab54-da09-527f-81f7-d63208dea377", "text": "a only"}, {"id": "e55745ef-a686-5b32-abdc-2f3f92f93a98", "text": "small and green"}, {"id": "23799c4b-276c-50a8-ab5b-9ff779f5b84f", "text": "a and turtle"}, {"id": "1b06c723-5d6f-507a-ae48-b36f94605c72", "text": "turtle only"}]}, {"id": "2d1f90f2-760b-5589-933e-8c752fcef92e", "prompt": "Which word describes a quality?", "options": [{"id": "88896777-4235-567a-815d-75362b7cd76b", "text": "kind"}, {"id": "8eda24ed-fbcb-5d56-bb44-00ca4ac416e5", "text": "basket"}, {"id": "590baf65-f498-5d04-864e-938dd70a6d0b", "text": "walk"}, {"id": "5f47977b-b75a-5c86-b985-ddef6f41d4d9", "text": "garden"}]}]}, "status": "published", "version": 1}, {"id": "d125809b-30ff-5537-9851-79fcdc187cd0", "owner_id": null, "kind": "game", "title": "Grade 3: Describe our animal friends — Word game", "grade_level": 3, "learning_level": "developing", "summary": "Match four lesson words with their Filipino meanings.", "source_label": "LinguaKids grade pathways · original supplemental enrichment v3", "body": {"cover_scene": 8, "unit_title": "Describe our animal friends", "pairs": [{"en": "small", "fil": "maliit"}, {"en": "bright", "fil": "matingkad"}, {"en": "kind", "fil": "mabait"}, {"en": "brave", "fil": "matapang"}]}, "status": "published", "version": 1}, {"id": "b2d2bd44-198d-5f08-946e-45a25db8d259", "owner_id": null, "kind": "lesson", "title": "Grade 3: One and many in the library", "grade_level": 3, "learning_level": "developing", "summary": "Four bilingual learning pages with examples and a practice task.", "source_label": "LinguaKids grade pathways · original supplemental enrichment v3", "body": {"cover_scene": 15, "unit_title": "One and many in the library", "pages": [{"english": "Singular means one. Plural means more than one. In English, many plural nouns are formed by adding s: book becomes books, and cat becomes cats.", "filipino": "Ang isahan ay tumutukoy sa isa. Ang maramihan ay higit sa isa. Sa English, maraming pangngalang maramihan ang nilalagyan ng s: book ay nagiging books at cat ay nagiging cats.", "scene": 15}, {"english": "Some words add es, such as box becoming boxes. Some change their spelling, such as child becoming children. Read the word carefully rather than adding s to every noun.", "filipino": "May mga salitang nilalagyan ng es, gaya ng box na nagiging boxes. May mga nagbabago ng baybay, gaya ng child na nagiging children. Basahing mabuti ang salita sa halip na laging magdagdag ng s.", "scene": 15}, {"english": "Read: One child brings two books. Child tells about one person. Books tells about more than one book. In Filipino, mga often helps show more than one: mga aklat.", "filipino": "Basahin: May dalang dalawang aklat ang isang bata. Isang tao ang tinutukoy ng child. Higit sa isang aklat ang tinutukoy ng books. Sa Filipino, nakakatulong ang mga upang magpahiwatig ng maramihan: mga aklat.", "scene": 15}, {"english": "Try it: Write the plural of book, box, and child. Use one plural noun in a sentence. Check whether the number word and the noun agree.", "filipino": "Subukan: Isulat ang maramihan ng book, box, at child. Gumamit ng isang pangngalang maramihan sa pangungusap. Suriin kung tugma ang bilang at ang pangngalan.", "scene": 15}]}, "status": "published", "version": 1}, {"id": "2b0d3e62-316e-5469-951a-23f5d9900716", "owner_id": null, "kind": "quiz", "title": "Grade 3: One and many in the library — Quiz", "grade_level": 3, "learning_level": "developing", "summary": "Six questions: vocabulary and applying the lesson. Tap A, B, C, or D.", "source_label": "LinguaKids grade pathways · original supplemental enrichment v3", "body": {"cover_scene": 15, "unit_title": "One and many in the library", "questions": [{"id": "8ca6b31a-439e-52a7-9b9a-02585271ab3f", "prompt": "Which Filipino word or phrase means \"book\"?", "options": [{"id": "4b38cf09-afc2-5428-a760-f5aa193ea9e6", "text": "mga bata"}, {"id": "da9664f3-260d-5db7-89d5-829f838fc67b", "text": "aklat"}, {"id": "d6986d3e-f28d-5ae6-8d14-c487641c1491", "text": "mga aklat"}, {"id": "1810d385-20a4-56b5-806f-12263f186a69", "text": "bata"}]}, {"id": "f687c43b-c6cd-5e77-b96e-4a62d6d4ad1b", "prompt": "Which Filipino word or phrase means \"books\"?", "options": [{"id": "5dc9037d-64bb-5710-b405-f8e27051844a", "text": "mga aklat"}, {"id": "5dc9e431-9d5b-5c63-866f-261735f86011", "text": "aklat"}, {"id": "0b4e9f91-add9-5f2b-8827-2d0f6defe1ff", "text": "bata"}, {"id": "abbb08f9-66ca-5316-8ce7-e891547c9622", "text": "mga bata"}]}, {"id": "e15b43e0-5ae8-5c4d-8174-9817fa62b85c", "prompt": "Which Filipino word or phrase means \"child\"?", "options": [{"id": "29da5d6d-d83d-5904-86c5-cac0c4d182dc", "text": "aklat"}, {"id": "27d6b14f-99f1-5817-aac9-94bb248631ad", "text": "mga aklat"}, {"id": "4be4944b-3081-539f-b29f-84d709a12eef", "text": "mga bata"}, {"id": "bdc69d32-6b55-56c9-b27d-7a260e013f20", "text": "bata"}]}, {"id": "d65ec0ec-81ac-5b45-98cb-cac579d4d53e", "prompt": "Which Filipino word or phrase means \"children\"?", "options": [{"id": "a5cd2159-48f9-54ca-8e5d-69ed2f52fa72", "text": "mga aklat"}, {"id": "036b633b-8de2-582f-9f45-589c011534dd", "text": "bata"}, {"id": "ec301b41-d6c5-5347-9d40-e212a42dcf9d", "text": "mga bata"}, {"id": "fa20ad82-2e86-536d-91b1-f410ad18df81", "text": "aklat"}]}, {"id": "742f7f67-644e-5286-a0ca-5b480f267dba", "prompt": "Which is the correct plural of box?", "options": [{"id": "06186124-ec99-5b5c-abab-3ecc101dd3b7", "text": "boxen"}, {"id": "c397af35-da42-576d-9a66-b1cac58e05fc", "text": "boxes"}, {"id": "770969db-9094-56fa-88a3-ceeae1b447df", "text": "boxs"}, {"id": "07b3dfa8-dad1-5be0-bc79-246c9e63099a", "text": "boxies"}]}, {"id": "e2e6046b-def4-565e-8d91-52e8b21adede", "prompt": "Which sentence uses the plural correctly?", "options": [{"id": "68c81365-b93c-5d4b-880a-e36aba3d6ee7", "text": "Two children read books."}, {"id": "d1baac8e-ca02-569d-9ffc-99a38837fae7", "text": "Two child read books."}, {"id": "af31fe0f-7137-50b0-bf2e-3b81dfbf5004", "text": "Two childs read book."}, {"id": "9eaee6d3-f987-514a-a340-7a4484606d84", "text": "Two childrens read book."}]}]}, "status": "published", "version": 1}, {"id": "d1488875-01bc-55cd-8d81-61135e039261", "owner_id": null, "kind": "game", "title": "Grade 3: One and many in the library — Word game", "grade_level": 3, "learning_level": "developing", "summary": "Match four lesson words with their Filipino meanings.", "source_label": "LinguaKids grade pathways · original supplemental enrichment v3", "body": {"cover_scene": 15, "unit_title": "One and many in the library", "pairs": [{"en": "book", "fil": "aklat"}, {"en": "books", "fil": "mga aklat"}, {"en": "child", "fil": "bata"}, {"en": "children", "fil": "mga bata"}]}, "status": "published", "version": 1}, {"id": "397f06b9-1c75-54eb-ac5f-64ab5318efa8", "owner_id": null, "kind": "lesson", "title": "Grade 3: First, next, and last", "grade_level": 3, "learning_level": "developing", "summary": "Four bilingual learning pages with examples and a practice task.", "source_label": "LinguaKids grade pathways · original supplemental enrichment v3", "body": {"cover_scene": 9, "unit_title": "First, next, and last", "pages": [{"english": "Sequence is the order in which events happen. Words such as first, next, then, and finally help readers follow instructions and stories.", "filipino": "Ang pagkakasunod-sunod ay ang ayos ng mga pangyayari. Nakakatulong ang una, kasunod, pagkatapos, at sa huli upang masundan ang panuto at kuwento.", "scene": 9}, {"english": "First, Milo puts soil in a pot. Next, he plants a seed. Then, he waters the soil gently. Finally, he puts the pot in a suitable sunny place.", "filipino": "Una, naglagay si Milo ng lupa sa paso. Kasunod, nagtanim siya ng binhi. Pagkatapos, marahan niyang diniligan ang lupa. Sa huli, inilagay niya ang paso sa angkop na maaraw na lugar.", "scene": 9}, {"english": "Changing the order can change the result. Planting a seed before there is soil will not work well. Look for clues that tell which step must happen before another.", "filipino": "Maaaring magbago ang resulta kapag binago ang ayos. Hindi maayos ang pagtatanim ng binhi kung wala pang lupa. Hanapin ang mga palatandaang nagsasabi kung aling hakbang ang kailangang mauna.", "scene": 9}, {"english": "Try it: Explain how you prepare a book for reading. Use first, next, and finally. Make each step clear enough for a friend to follow.", "filipino": "Subukan: Ipaliwanag kung paano ka naghahanda ng aklat para bumasa. Gamitin ang una, kasunod, at sa huli. Gawing malinaw ang bawat hakbang upang masundan ng kaibigan.", "scene": 9}]}, "status": "published", "version": 1}, {"id": "386343e1-d5e3-5caf-adf0-1c0eee1e7857", "owner_id": null, "kind": "quiz", "title": "Grade 3: First, next, and last — Quiz", "grade_level": 3, "learning_level": "developing", "summary": "Six questions: vocabulary and applying the lesson. Tap A, B, C, or D.", "source_label": "LinguaKids grade pathways · original supplemental enrichment v3", "body": {"cover_scene": 9, "unit_title": "First, next, and last", "questions": [{"id": "3189e208-cd59-5e76-b41a-5be71672a744", "prompt": "Which Filipino word or phrase means \"first\"?", "options": [{"id": "982a71e1-89ac-5f86-8bf8-35080ca3d13f", "text": "sa huli"}, {"id": "38b680a0-40aa-56af-82fd-d294599c75a0", "text": "una"}, {"id": "8debdc4c-12fd-5df3-ab99-a36ca5cfbf49", "text": "kasunod"}, {"id": "7e8438cb-ca86-5f88-a671-73e63ab6941c", "text": "pagkatapos"}]}, {"id": "f91b5879-c83b-5f33-8bd3-70b53b13c535", "prompt": "Which Filipino word or phrase means \"next\"?", "options": [{"id": "960f3c9c-affe-5e4b-bee5-9fab8fddd352", "text": "kasunod"}, {"id": "8faed55a-ab4c-5ae8-a238-f654a3c75582", "text": "una"}, {"id": "e1d7dc37-5136-5870-8a5a-e433a9d8de9e", "text": "pagkatapos"}, {"id": "7760bc0f-01d3-56e8-bb13-817f056c37f3", "text": "sa huli"}]}, {"id": "cf5f1e2d-5388-5268-ac33-6e0999d4f9cc", "prompt": "Which Filipino word or phrase means \"then\"?", "options": [{"id": "a4db619b-5ca5-5e8f-9509-3c99731bcc86", "text": "una"}, {"id": "2eac0b20-9572-5ee9-8249-bd79c5eb90a9", "text": "kasunod"}, {"id": "262e5678-7d97-51a7-a60e-7201a073f4ad", "text": "sa huli"}, {"id": "bb05d72c-98cc-58f6-be12-c931217bcdc0", "text": "pagkatapos"}]}, {"id": "87ba20e7-d44f-509d-97ef-58a127ab30fb", "prompt": "Which Filipino word or phrase means \"finally\"?", "options": [{"id": "8c3714cb-0c8a-51c1-a498-4e7e1849f54d", "text": "kasunod"}, {"id": "87f371c8-24fa-5e16-bf8c-c6efd28aec30", "text": "pagkatapos"}, {"id": "adcdc4ae-01f1-51ed-9444-c3e52ec14ea3", "text": "sa huli"}, {"id": "245d8c89-623b-587e-a96e-dc9f5bf20eb6", "text": "una"}]}, {"id": "eaf35032-6a7a-5e00-8da6-bc2c6e333ddf", "prompt": "What does Milo do immediately after planting the seed?", "options": [{"id": "a342bbee-0f3b-5e24-b961-0afe7bfa6489", "text": "He removes the pot."}, {"id": "c9d9caf1-a768-5e58-850e-90d9baccdf94", "text": "He waters the soil."}, {"id": "d99a3d8d-f7f3-5ae9-943e-96e0411b3858", "text": "He adds the first soil."}, {"id": "2e459b97-6b60-5375-84fe-5faea7a4168b", "text": "He harvests tomatoes."}]}, {"id": "13f0eb83-8be4-5131-bc40-b7561df585dd", "prompt": "Which word usually signals the last step?", "options": [{"id": "288ca3bf-17f1-5470-978b-6e47f933ffd8", "text": "finally"}, {"id": "bf89b301-f818-5a80-a4ef-0115b3a9a7c7", "text": "first"}, {"id": "efe46d54-6148-526d-b456-2040b7434dd2", "text": "before"}, {"id": "1a465e10-b145-5506-a1fb-a4cc43ad07a9", "text": "next"}]}]}, "status": "published", "version": 1}, {"id": "92c532c3-6ba2-589b-a4a5-4d5bcd64be00", "owner_id": null, "kind": "game", "title": "Grade 3: First, next, and last — Word game", "grade_level": 3, "learning_level": "developing", "summary": "Match four lesson words with their Filipino meanings.", "source_label": "LinguaKids grade pathways · original supplemental enrichment v3", "body": {"cover_scene": 9, "unit_title": "First, next, and last", "pairs": [{"en": "first", "fil": "una"}, {"en": "next", "fil": "kasunod"}, {"en": "then", "fil": "pagkatapos"}, {"en": "finally", "fil": "sa huli"}]}, "status": "published", "version": 1}, {"id": "6e2efd8b-3b04-5581-9fe3-fa79c829b914", "owner_id": null, "kind": "lesson", "title": "Grade 4: Yesterday, today, and tomorrow", "grade_level": 4, "learning_level": "developing", "summary": "Four bilingual learning pages with examples and a practice task.", "source_label": "LinguaKids grade pathways · original supplemental enrichment v3", "body": {"cover_scene": 0, "unit_title": "Yesterday, today, and tomorrow", "pages": [{"english": "Verb tense helps show when an action happens. A simple past action happened before now. A simple present action can tell a habit. A future action will happen later.", "filipino": "Nakakatulong ang panahunan ng pandiwa upang ipakita kung kailan nangyayari ang kilos. Naganap na ang kilos sa nakaraan. Maaaring ipakita ng kasalukuyan ang nakagawian. Magaganap pa ang kilos sa hinaharap.", "scene": 0}, {"english": "Read: Finn walked yesterday. Finn walks every morning. Finn will walk tomorrow. Walked shows the past, walks shows a present habit, and will walk shows the future.", "filipino": "Basahin: Naglakad si Finn kahapon. Naglalakad si Finn tuwing umaga. Maglalakad si Finn bukas. Ipinapakita ng mga pandiwa ang nakaraan, nakagawiang kilos, at hinaharap.", "scene": 0}, {"english": "Time clues help you choose a verb. Yesterday and last week point to the past. Every day can point to a habit. Tomorrow and next week point to the future. Some past forms are irregular: go becomes went.", "filipino": "Nakakatulong ang mga pahiwatig ng oras sa pagpili ng pandiwa. Nakaraan ang kahapon at nakaraang linggo. Nakagawiang kilos ang maaaring tukuyin ng araw-araw. Hinaharap ang bukas at susunod na linggo. May di-karaniwang anyo: go ay nagiging went.", "scene": 0}, {"english": "Try it: Complete three sentences about reading: Yesterday I ___. Every day I ___. Tomorrow I will ___. Use the time clue to check each verb.", "filipino": "Subukan: Kumpletuhin ang tatlong pangungusap tungkol sa pagbasa: Kahapon ay ___. Araw-araw ay ___. Bukas ay ___. Gamitin ang pahiwatig ng oras upang suriin ang pandiwa.", "scene": 0}]}, "status": "published", "version": 1}, {"id": "6e5d375f-a696-57a4-a672-0e7d4e8b9fd5", "owner_id": null, "kind": "quiz", "title": "Grade 4: Yesterday, today, and tomorrow — Quiz", "grade_level": 4, "learning_level": "developing", "summary": "Six questions: vocabulary and applying the lesson. Tap A, B, C, or D.", "source_label": "LinguaKids grade pathways · original supplemental enrichment v3", "body": {"cover_scene": 0, "unit_title": "Yesterday, today, and tomorrow", "questions": [{"id": "ab61f545-b6ff-51e5-ab5a-efcecd55d289", "prompt": "Which Filipino word or phrase means \"yesterday\"?", "options": [{"id": "d8b451f3-e870-5e3b-812c-39117e9577ff", "text": "kahapon"}, {"id": "234910d3-5c37-5a22-a702-6b6e30b87e66", "text": "ngayon"}, {"id": "d0fbdd21-7e52-58f9-8d2c-4e1090ee5972", "text": "bukas"}, {"id": "db052109-3649-58d8-8c44-568a54039387", "text": "araw-araw"}]}, {"id": "29858ff4-216a-5c99-872b-eceb805a1b59", "prompt": "Which Filipino word or phrase means \"today\"?", "options": [{"id": "e4565e2e-e764-551b-bf21-fddd11f9edbf", "text": "kahapon"}, {"id": "35b8ebd0-3dee-56d3-85ba-07210cb6fd4c", "text": "bukas"}, {"id": "a3a62429-947d-51ac-ac8e-7e5ec7c8b20f", "text": "araw-araw"}, {"id": "bfe696ff-4100-553e-b813-e388150f92d7", "text": "ngayon"}]}, {"id": "3186e441-e961-56b3-9c35-04836b5bb97a", "prompt": "Which Filipino word or phrase means \"tomorrow\"?", "options": [{"id": "05f7ca54-f6db-5a31-9a60-bd05e372adf2", "text": "ngayon"}, {"id": "3955d5bf-3ecc-54a4-86fb-fc766f9e6363", "text": "araw-araw"}, {"id": "d96f93e9-cd38-5ba9-b3f0-52f8c8b09e49", "text": "bukas"}, {"id": "da35a4ac-0c55-50bf-bb85-260d7d9fbb58", "text": "kahapon"}]}, {"id": "8a93f242-d5d2-5749-b069-c881f56bb957", "prompt": "Which Filipino word or phrase means \"every day\"?", "options": [{"id": "c1283de9-4e77-54a6-8bb6-83174067d7b6", "text": "bukas"}, {"id": "cf86cd0a-d1d5-5be4-8493-f892c2484331", "text": "araw-araw"}, {"id": "ef841ca6-6dc7-554e-8747-013ce87a37b3", "text": "kahapon"}, {"id": "5572dda5-cf09-5eb0-b61a-96093f4e2b6c", "text": "ngayon"}]}, {"id": "50962c59-7b04-56fe-91ab-a00a34f45053", "prompt": "Choose the correct verb: Yesterday, Finn ___ to school.", "options": [{"id": "9a9ee3ac-5218-5639-936c-16eff8fc03fa", "text": "walked"}, {"id": "70eb2d31-9975-54e0-b81a-0c6fc675e2aa", "text": "walks"}, {"id": "a1f7e483-e2b1-5dd8-9e2b-67252929df7a", "text": "will walk"}, {"id": "94b570ad-ca8d-5e0b-b7cf-cd4b463120c1", "text": "walking"}]}, {"id": "a34a7ed6-06fe-59aa-bbd6-a525094a0046", "prompt": "Which sentence tells a future action?", "options": [{"id": "1069a14f-2bc5-5599-af98-7ad6c202cb06", "text": "Luna read yesterday."}, {"id": "d162d772-4e33-56b1-bc37-c63cf8490a81", "text": "Luna reads every night."}, {"id": "615c6064-a274-57f7-963c-b43627ce18f8", "text": "Luna is reading now."}, {"id": "72777aaa-369c-5711-a50b-4673b8e94f47", "text": "Luna will read tomorrow."}]}]}, "status": "published", "version": 1}, {"id": "535f76e8-398c-530b-8d6e-d3d75c3ffa76", "owner_id": null, "kind": "game", "title": "Grade 4: Yesterday, today, and tomorrow — Word game", "grade_level": 4, "learning_level": "developing", "summary": "Match four lesson words with their Filipino meanings.", "source_label": "LinguaKids grade pathways · original supplemental enrichment v3", "body": {"cover_scene": 0, "unit_title": "Yesterday, today, and tomorrow", "pairs": [{"en": "yesterday", "fil": "kahapon"}, {"en": "today", "fil": "ngayon"}, {"en": "tomorrow", "fil": "bukas"}, {"en": "every day", "fil": "araw-araw"}]}, "status": "published", "version": 1}, {"id": "37975f23-c2f6-51bf-970a-f347eb46962f", "owner_id": null, "kind": "lesson", "title": "Grade 4: Why the garden grew", "grade_level": 4, "learning_level": "developing", "summary": "Four bilingual learning pages with examples and a practice task.", "source_label": "LinguaKids grade pathways · original supplemental enrichment v3", "body": {"cover_scene": 10, "unit_title": "Why the garden grew", "pages": [{"english": "A cause tells why something happens. An effect tells what happens as a result. Connecting these ideas helps us explain events rather than only list them.", "filipino": "Sinasabi ng sanhi kung bakit nangyayari ang isang bagay. Sinasabi ng bunga ang resulta. Nakakatulong ang pag-uugnay sa mga ito upang maipaliwanag ang mga pangyayari sa halip na ilista lamang.", "scene": 10}, {"english": "Read: The soil was dry, so Milo watered the garden. The dry soil is the cause of his decision. Watering the garden is the effect. The word so often introduces a result.", "filipino": "Basahin: Tuyo ang lupa kaya diniligan ni Milo ang hardin. Ang tuyong lupa ang sanhi ng kaniyang pasiya. Ang pagdidilig ang bunga. Madalas ipakilala ng kaya ang resulta.", "scene": 10}, {"english": "Read: The path became wet because rain fell. Rain falling is the cause even though it appears later in the sentence. Because helps explain why. Word order alone does not identify cause and effect.", "filipino": "Basahin: Nabasa ang daan dahil umulan. Ang pag-ulan ang sanhi kahit nasa hulihan ito ng pangungusap. Ipinapaliwanag ng dahil ang dahilan. Hindi sapat ang ayos ng salita lamang upang matukoy ang sanhi at bunga.", "scene": 10}, {"english": "Try it: Explain why you carry an umbrella on a rainy day. Name the cause and effect. Use because or so, and make sure the connection is reasonable.", "filipino": "Subukan: Ipaliwanag kung bakit nagdadala ka ng payong sa maulang araw. Tukuyin ang sanhi at bunga. Gamitin ang dahil o kaya at tiyaking makatuwiran ang ugnayan.", "scene": 10}]}, "status": "published", "version": 1}, {"id": "bc433397-8102-58e2-b3f0-9cc82f78ba8d", "owner_id": null, "kind": "quiz", "title": "Grade 4: Why the garden grew — Quiz", "grade_level": 4, "learning_level": "developing", "summary": "Six questions: vocabulary and applying the lesson. Tap A, B, C, or D.", "source_label": "LinguaKids grade pathways · original supplemental enrichment v3", "body": {"cover_scene": 10, "unit_title": "Why the garden grew", "questions": [{"id": "c0538e90-6fb9-5e0c-a5eb-38ca1390a6c7", "prompt": "Which Filipino word or phrase means \"cause\"?", "options": [{"id": "4fecc1cd-0430-5e3e-9824-66d4229593de", "text": "sanhi"}, {"id": "688bc43c-892b-5d11-80d1-24172ebe0686", "text": "bunga"}, {"id": "e32ab023-286f-58c7-9c9f-1f835698147a", "text": "dahil"}, {"id": "ba1c57b3-96e8-5ca5-b0e8-cff6c6ce1fba", "text": "resulta"}]}, {"id": "b27eff73-dcd6-5009-9531-107bdc979483", "prompt": "Which Filipino word or phrase means \"effect\"?", "options": [{"id": "cb54adf8-1054-57ee-8949-01e6653db867", "text": "sanhi"}, {"id": "6221df87-dcaa-5abd-8a8a-e069b9d411e1", "text": "dahil"}, {"id": "d8ddaffc-93df-5a98-8fbb-9cf9b673d091", "text": "resulta"}, {"id": "82cd5643-f7b7-56d1-b1dc-1462ebd5cf3d", "text": "bunga"}]}, {"id": "f8884fac-89ba-583b-a37e-2de4a266e203", "prompt": "Which Filipino word or phrase means \"because\"?", "options": [{"id": "ffca028c-209c-5acb-8298-08ef74420b47", "text": "bunga"}, {"id": "ae360a36-5752-55ca-8e2c-c031514c9b49", "text": "resulta"}, {"id": "4ed07e3c-3aa2-54cd-8984-db284361da09", "text": "dahil"}, {"id": "cc5a1749-d2cd-5bea-8eb0-b7b9089faab2", "text": "sanhi"}]}, {"id": "a4c138e7-ec4a-5ded-abfa-85d3a0dc7043", "prompt": "Which Filipino word or phrase means \"result\"?", "options": [{"id": "4f4ac57e-52a9-5d51-9afc-e7d44e3c3b8a", "text": "dahil"}, {"id": "e352a83b-0500-5fbe-9888-072b0dadd845", "text": "resulta"}, {"id": "c0dd9e3c-f891-5a10-8f21-7b0c371a934a", "text": "sanhi"}, {"id": "6e423dc1-196c-5a98-935b-f62762902f19", "text": "bunga"}]}, {"id": "11f2d5cb-a10a-57c9-b2b4-7f7ef8b9def7", "prompt": "Rain fell, so the path became wet. What is the cause?", "options": [{"id": "51c4c7be-4665-5938-8819-3311791772a8", "text": "Rain fell."}, {"id": "02cf4472-d205-5298-ba2c-32502f6c06a4", "text": "The path became wet."}, {"id": "3b840fa9-c8da-5732-a821-1394658a9fd8", "text": "The sun rose."}, {"id": "10745c3b-1eb8-5f60-86f2-f5498ed2b05c", "text": "Milo read a book."}]}, {"id": "69f314c7-70e3-533d-b8af-f353b222539a", "prompt": "Which sentence gives a reasonable cause and effect?", "options": [{"id": "fca60d1a-7e86-5e27-b308-505950b49583", "text": "The book was purple, so the sea became salty."}, {"id": "b991f489-7a4d-5135-9180-d397e05ab305", "text": "The turtle smiled, so yesterday became tomorrow."}, {"id": "4c991ee6-5296-590f-9978-f788dc42c4a1", "text": "The pot was round, so all birds stopped flying."}, {"id": "be11a826-fd8d-5e28-9a14-e8cc0ee91b9e", "text": "The plant lacked water, so its leaves wilted."}]}]}, "status": "published", "version": 1}, {"id": "0b967ae1-1063-5e58-ac7c-75b2f69ff446", "owner_id": null, "kind": "game", "title": "Grade 4: Why the garden grew — Word game", "grade_level": 4, "learning_level": "developing", "summary": "Match four lesson words with their Filipino meanings.", "source_label": "LinguaKids grade pathways · original supplemental enrichment v3", "body": {"cover_scene": 10, "unit_title": "Why the garden grew", "pairs": [{"en": "cause", "fil": "sanhi"}, {"en": "effect", "fil": "bunga"}, {"en": "because", "fil": "dahil"}, {"en": "result", "fil": "resulta"}]}, "status": "published", "version": 1}, {"id": "14467954-7c31-5a56-8c71-737799a3b68d", "owner_id": null, "kind": "lesson", "title": "Grade 4: Compare the forest and the reef", "grade_level": 4, "learning_level": "developing", "summary": "Four bilingual learning pages with examples and a practice task.", "source_label": "LinguaKids grade pathways · original supplemental enrichment v3", "body": {"cover_scene": 4, "unit_title": "Compare the forest and the reef", "pages": [{"english": "To compare is to find similarities. To contrast is to find differences. Read both things carefully before deciding what they share and what makes each different.", "filipino": "Ang paghahambing ay pagtingin sa pagkakatulad. Ang pagtukoy sa kaibahan ay pagtingin sa pagkakaiba. Basahing mabuti ang dalawang bagay bago magpasiya kung ano ang magkatulad at naiiba.", "scene": 4}, {"english": "A forest has trees and many land animals. A reef is underwater and shelters many sea animals. Both are habitats where living things find what they need.", "filipino": "May mga puno at maraming hayop sa lupa sa kagubatan. Nasa ilalim ng dagat ang bahura at kanlungan ito ng mga hayop-dagat. Pareho silang tirahang pinagkukunan ng kailangan ng mga nilalang.", "scene": 4}, {"english": "Use both or similarly for a similarity. Use unlike or however for a difference. Both Finn and Ollie help friends. Unlike Finn, Ollie lives in the ocean.", "filipino": "Gamitin ang pareho o gayundin para sa pagkakatulad. Gamitin ang di-tulad o subalit para sa kaibahan. Parehong tumutulong sa kaibigan sina Finn at Ollie. Di-tulad ni Finn, nasa dagat si Ollie.", "scene": 4}, {"english": "Try it: Compare a storybook and a dictionary. Give one similarity and one difference. Support each idea by naming a feature of the two books.", "filipino": "Subukan: Ihambing ang aklat ng kuwento at diksiyonaryo. Magbigay ng isang pagkakatulad at isang pagkakaiba. Suportahan ang bawat ideya gamit ang katangian ng dalawang aklat.", "scene": 4}]}, "status": "published", "version": 1}, {"id": "5830107f-374f-5ac3-b388-a4c37dbc8e6a", "owner_id": null, "kind": "quiz", "title": "Grade 4: Compare the forest and the reef — Quiz", "grade_level": 4, "learning_level": "developing", "summary": "Six questions: vocabulary and applying the lesson. Tap A, B, C, or D.", "source_label": "LinguaKids grade pathways · original supplemental enrichment v3", "body": {"cover_scene": 4, "unit_title": "Compare the forest and the reef", "questions": [{"id": "66f38ae2-1564-59ba-b84c-c269627214ad", "prompt": "Which Filipino word or phrase means \"similar\"?", "options": [{"id": "57232436-a6a6-5715-984a-508b13e674c9", "text": "magkatulad"}, {"id": "4003fccd-20dd-5647-91dc-eec68e29b92d", "text": "magkaiba"}, {"id": "68a0480c-40d9-5f3b-a0e4-193f334479a9", "text": "pareho"}, {"id": "6dfdd5de-fd3d-5ab8-8b2d-10aa8de99c4b", "text": "tirahan"}]}, {"id": "375dc7aa-bd42-5c10-a5da-77de8dc438f0", "prompt": "Which Filipino word or phrase means \"different\"?", "options": [{"id": "255d02f5-964b-57f7-b7e7-f2e018ef07f4", "text": "magkatulad"}, {"id": "824970f2-2237-5ef9-ab30-da30ace6110b", "text": "pareho"}, {"id": "8948f71f-9d3e-5bac-ad4c-5118a8deb8d9", "text": "tirahan"}, {"id": "94837b29-0fe3-5fc0-913d-984a1f266d6a", "text": "magkaiba"}]}, {"id": "c588dfe4-3f05-53c0-9e62-531708ea2961", "prompt": "Which Filipino word or phrase means \"both\"?", "options": [{"id": "c300bb3c-f540-5bb5-ba9d-ae017dd9805d", "text": "magkaiba"}, {"id": "b6139970-35fe-5b3b-a9af-0e4c728fc813", "text": "tirahan"}, {"id": "a8c4c0b0-d03f-5624-a1b0-099eb239fe4e", "text": "pareho"}, {"id": "86d88109-5564-5778-9672-de0a973c4c3f", "text": "magkatulad"}]}, {"id": "613ae640-53f5-5b2d-b6da-3f1f244f74cc", "prompt": "Which Filipino word or phrase means \"habitat\"?", "options": [{"id": "b41a2484-c297-5656-b451-27a88323e603", "text": "pareho"}, {"id": "9d8d1214-e748-5410-a86b-17b8e10a0825", "text": "tirahan"}, {"id": "2d4bf144-6683-5581-9c77-f78c4a8da4cb", "text": "magkatulad"}, {"id": "e9075b4d-1069-5b5e-864d-d665b3c39a8c", "text": "magkaiba"}]}, {"id": "b55e1584-e20a-5773-8148-d16b51e10af6", "prompt": "What do a forest and a reef have in common?", "options": [{"id": "7cb52f34-378c-5f70-ba78-3aeaba76d31b", "text": "Both are habitats."}, {"id": "57ae361d-076e-5f84-82a1-bbc76c613fbc", "text": "Both are always dry."}, {"id": "0c617247-0d4c-56d5-84db-d2ef14a10f54", "text": "Both have only land animals."}, {"id": "40aaf0b1-690a-5a74-bc96-b4e7c2ca0696", "text": "Both are above the clouds."}]}, {"id": "3c982b92-c6b2-5068-9dbb-2e462d5ba969", "prompt": "Which sentence contrasts Finn and Ollie?", "options": [{"id": "4bf6b834-561d-5fd0-8f3c-9327994f3588", "text": "Both help their friends."}, {"id": "f94722b6-c448-5a76-9e41-7c7f653520be", "text": "Both can be kind."}, {"id": "4bbec0df-f135-5120-81fe-b5ff657af32a", "text": "Both appear in stories."}, {"id": "f8bd6eb1-8099-5f0f-a9f1-a02149c7c6f0", "text": "Finn lives on land, while Ollie lives in the ocean."}]}]}, "status": "published", "version": 1}, {"id": "5a313357-68b8-51e8-967d-d4b50d7613ba", "owner_id": null, "kind": "game", "title": "Grade 4: Compare the forest and the reef — Word game", "grade_level": 4, "learning_level": "developing", "summary": "Match four lesson words with their Filipino meanings.", "source_label": "LinguaKids grade pathways · original supplemental enrichment v3", "body": {"cover_scene": 4, "unit_title": "Compare the forest and the reef", "pairs": [{"en": "similar", "fil": "magkatulad"}, {"en": "different", "fil": "magkaiba"}, {"en": "both", "fil": "pareho"}, {"en": "habitat", "fil": "tirahan"}]}, "status": "published", "version": 1}, {"id": "c27b292f-ccaf-5a29-8dd6-d3c8f36e70b3", "owner_id": null, "kind": "lesson", "title": "Grade 5: Find the main idea", "grade_level": 5, "learning_level": "independent", "summary": "Four bilingual learning pages with examples and a practice task.", "source_label": "LinguaKids grade pathways · original supplemental enrichment v3", "body": {"cover_scene": 15, "unit_title": "Find the main idea", "pages": [{"english": "The main idea is what a paragraph is mostly about. Supporting details explain or give examples of that idea. A title or topic sentence can help, but read the whole paragraph.", "filipino": "Ang pangunahing ideya ang pinakabuod ng talata. Nagpapaliwanag o nagbibigay ng halimbawa ang mga pantulong na detalye. Maaaring makatulong ang pamagat o paksang pangungusap, ngunit basahin ang buong talata.", "scene": 15}, {"english": "Read: Luna keeps the library welcoming. She arranges cushions, labels the shelves, and helps new readers choose books. Each detail shows how Luna makes the library welcoming.", "filipino": "Basahin: Pinananatiling magiliw ni Luna ang aklatan. Inaayos niya ang mga unan, nilalagyan ng tanda ang mga istante, at tinutulungan ang bagong mambabasa na pumili ng aklat. Ipinapakita ng bawat detalye ang magiliw na aklatan.", "scene": 15}, {"english": "The paragraph is mostly about making the library welcoming. It is not mostly about cushions alone. A main idea should include the important details without becoming so broad that it says almost nothing.", "filipino": "Tungkol sa pagiging magiliw ng aklatan ang talata. Hindi lamang tungkol sa mga unan ang paksa. Dapat masaklaw ng pangunahing ideya ang mahahalagang detalye nang hindi nagiging sobrang malawak o malabo.", "scene": 15}, {"english": "Try it: Write a one-sentence main idea for the paragraph. Then list two supporting details. Ask whether each detail helps explain your main idea.", "filipino": "Subukan: Isulat sa isang pangungusap ang pangunahing ideya ng talata. Maglista ng dalawang pantulong na detalye. Suriin kung nakakatulong ang bawat detalye sa pagpapaliwanag ng pangunahing ideya.", "scene": 15}]}, "status": "published", "version": 1}, {"id": "d108b6ab-de37-5125-bd2d-6a06769d58e6", "owner_id": null, "kind": "quiz", "title": "Grade 5: Find the main idea — Quiz", "grade_level": 5, "learning_level": "independent", "summary": "Six questions: vocabulary and applying the lesson. Tap A, B, C, or D.", "source_label": "LinguaKids grade pathways · original supplemental enrichment v3", "body": {"cover_scene": 15, "unit_title": "Find the main idea", "questions": [{"id": "dbd7f84d-817f-5989-851c-3ff8c6256fb9", "prompt": "Which Filipino word or phrase means \"main idea\"?", "options": [{"id": "49fbfd4a-9860-56f2-a174-d71ab334d678", "text": "detalye"}, {"id": "001e9b09-abd7-53a5-aa56-0bb5bc8789aa", "text": "talata"}, {"id": "23b32c00-b532-5b76-b849-9baa112f4a0d", "text": "pamagat"}, {"id": "d633a03d-4aef-55e2-9b00-34d5079777fd", "text": "pangunahing ideya"}]}, {"id": "c4932fce-a1fe-53be-92bb-7e8ba8114098", "prompt": "Which Filipino word or phrase means \"detail\"?", "options": [{"id": "7717c365-a8e0-595d-a3ab-73e2316b135e", "text": "talata"}, {"id": "b2fb2ec6-ecf6-53ed-9395-2a590d502655", "text": "pamagat"}, {"id": "ef509859-3e38-5840-86f2-7e1b7c21882e", "text": "detalye"}, {"id": "d457dfd9-9254-5b41-b799-b38d4b83e9cb", "text": "pangunahing ideya"}]}, {"id": "22cd495b-fe6f-58eb-8368-131650a60a95", "prompt": "Which Filipino word or phrase means \"paragraph\"?", "options": [{"id": "25b689e8-b11c-57fa-99a5-291d2658398a", "text": "pamagat"}, {"id": "51c4b173-75ae-55c4-851f-ae9b4f2ba935", "text": "talata"}, {"id": "54584828-83c7-5705-bf90-1695c50020f8", "text": "pangunahing ideya"}, {"id": "dcbafade-33ba-57ad-864b-17211d711472", "text": "detalye"}]}, {"id": "0defd3e1-fe66-5eda-8666-8f3405fafe4e", "prompt": "Which Filipino word or phrase means \"title\"?", "options": [{"id": "a7187484-2439-5bc2-86a2-d1e5450c269d", "text": "pamagat"}, {"id": "1bd0ccfe-f15b-50ea-b844-8d34045e6ce3", "text": "pangunahing ideya"}, {"id": "755d52d4-8ec6-516c-830d-9f19d8f542ac", "text": "detalye"}, {"id": "0c27d389-54ed-5098-ad85-c3543384651b", "text": "talata"}]}, {"id": "5a35172c-b1de-5419-a9e1-5593aa564f7d", "prompt": "What is the library paragraph mostly about?", "options": [{"id": "90e8dd8b-288a-5abe-b172-9e8fe770a773", "text": "Cushions are always purple."}, {"id": "cd349416-528d-52fa-b4de-12fcc6389262", "text": "All books are new."}, {"id": "6e10f049-acbb-5b52-81b9-187d8279b204", "text": "Luna dislikes reading."}, {"id": "26a549f7-4508-5b68-b633-ed5bf85a0146", "text": "Luna makes the library welcoming."}]}, {"id": "6260d3c5-17b3-5a8c-9558-8d1bce7b94de", "prompt": "Which detail supports the main idea?", "options": [{"id": "18d48798-f2c6-5f49-a0e1-ad5ec3344090", "text": "Finn likes apples."}, {"id": "3f7ec2b8-026a-580f-9662-baf32b10c4f6", "text": "Some turtles swim."}, {"id": "ca340be1-86c5-5f34-8664-ec77f682a593", "text": "She helps new readers choose books."}, {"id": "cf21211b-4c02-546e-9996-2b78bdd8ebb6", "text": "The ocean has coral."}]}]}, "status": "published", "version": 1}, {"id": "2ab1f7fe-a5d0-53e1-ab8f-790b4659021b", "owner_id": null, "kind": "game", "title": "Grade 5: Find the main idea — Word game", "grade_level": 5, "learning_level": "independent", "summary": "Match four lesson words with their Filipino meanings.", "source_label": "LinguaKids grade pathways · original supplemental enrichment v3", "body": {"cover_scene": 15, "unit_title": "Find the main idea", "pairs": [{"en": "main idea", "fil": "pangunahing ideya"}, {"en": "detail", "fil": "detalye"}, {"en": "paragraph", "fil": "talata"}, {"en": "title", "fil": "pamagat"}]}, "status": "published", "version": 1}, {"id": "ecace610-e05a-56ef-b193-73797b72e821", "owner_id": null, "kind": "lesson", "title": "Grade 5: Use context clues", "grade_level": 5, "learning_level": "independent", "summary": "Four bilingual learning pages with examples and a practice task.", "source_label": "LinguaKids grade pathways · original supplemental enrichment v3", "body": {"cover_scene": 5, "unit_title": "Use context clues", "pages": [{"english": "Context clues are nearby words and ideas that help explain an unfamiliar word. Look for a definition, example, contrast, or explanation before guessing a meaning.", "filipino": "Ang mga pahiwatig sa konteksto ay mga kalapit na salita at ideyang nagpapaliwanag sa di-pamilyar na salita. Humanap ng kahulugan, halimbawa, kaibahan, o paliwanag bago hulaan ang ibig sabihin.", "scene": 5}, {"english": "Read: The reef was pristine, clean and free of litter. The words clean and free of litter explain pristine. We can use the explanation as evidence for the meaning.", "filipino": "Basahin: Malinis at walang kalat ang pristine na bahura. Ipinapaliwanag ng malinis at walang kalat ang pristine. Maaaring gawing batayan ang paliwanag upang maunawaan ang kahulugan.", "scene": 5}, {"english": "Read: Pip was timid at first, but later he greeted everyone with confidence. The contrast between timid and confidence suggests that timid means shy, not loud or fearless.", "filipino": "Basahin: Timid si Pip noong una, ngunit kalaunan ay bumati siya nang may kumpiyansa. Ipinapahiwatig ng kaibahan ng timid at kumpiyansa na mahiyain ang ibig sabihin nito, hindi maingay o walang takot.", "scene": 5}, {"english": "Try it: Underline the clue that helps explain pristine. Then explain timid using the contrast in the second example. Check a dictionary when the clues are not enough.", "filipino": "Subukan: Salungguhitan ang pahiwatig na nagpapaliwanag sa pristine. Ipaliwanag naman ang timid gamit ang kaibahan sa ikalawang halimbawa. Gumamit ng diksiyonaryo kapag kulang ang mga pahiwatig.", "scene": 5}]}, "status": "published", "version": 1}, {"id": "2725383c-47b5-5be6-92d2-8ac9e9051063", "owner_id": null, "kind": "quiz", "title": "Grade 5: Use context clues — Quiz", "grade_level": 5, "learning_level": "independent", "summary": "Six questions: vocabulary and applying the lesson. Tap A, B, C, or D.", "source_label": "LinguaKids grade pathways · original supplemental enrichment v3", "body": {"cover_scene": 5, "unit_title": "Use context clues", "questions": [{"id": "e39f42bd-a9b5-519b-b5db-ae96245b2d82", "prompt": "Which Filipino word or phrase means \"pristine\"?", "options": [{"id": "992a9d26-8704-5616-b233-265f753d5a1a", "text": "mahiyain"}, {"id": "afee01d0-d9e3-55fa-a465-953df131891a", "text": "pahiwatig"}, {"id": "413519a1-c61d-5787-8e5b-84cbff653e24", "text": "kumpiyansa"}, {"id": "f714b2d7-6487-5ba7-aa07-9f18a9548010", "text": "malinis at di-nadungisan"}]}, {"id": "5353e06a-0f70-5e9f-b256-ba4516cf1cf3", "prompt": "Which Filipino word or phrase means \"timid\"?", "options": [{"id": "f8377801-f98e-5e6b-81e9-47b68fc43d63", "text": "pahiwatig"}, {"id": "ba00ce8b-c3b9-5861-968e-e916371d65c8", "text": "kumpiyansa"}, {"id": "45048b5c-5b71-5d77-be94-8774d103414e", "text": "mahiyain"}, {"id": "ddd86433-2b2d-52c4-b97a-3e7039b04e77", "text": "malinis at di-nadungisan"}]}, {"id": "ee8093b0-2158-549a-8222-b20184414daf", "prompt": "Which Filipino word or phrase means \"clue\"?", "options": [{"id": "fdc4797c-aff0-587a-bc70-b8a5fe213344", "text": "kumpiyansa"}, {"id": "3f067b5d-a17f-54e5-972a-0494565f5b8c", "text": "pahiwatig"}, {"id": "87204386-ddfb-55f3-9a35-8de1d2db2153", "text": "malinis at di-nadungisan"}, {"id": "aaa8904b-625a-58b3-acea-49abe11dc651", "text": "mahiyain"}]}, {"id": "e74deed3-24b7-5cd4-b58b-6fd80cd0a132", "prompt": "Which Filipino word or phrase means \"confidence\"?", "options": [{"id": "85adba64-9827-5585-807b-063ab76809ac", "text": "kumpiyansa"}, {"id": "270468c7-83b1-5dc1-baf7-a3c53be5cdc5", "text": "malinis at di-nadungisan"}, {"id": "9bdc1ac1-8055-5373-bb5c-cf574d6fa615", "text": "mahiyain"}, {"id": "31674a97-0ba6-514b-b3a5-1f54794fe9c9", "text": "pahiwatig"}]}, {"id": "98349275-3f9d-558e-9f2f-f48a25fb96e6", "prompt": "The reef was pristine, clean and free of litter. What explains pristine?", "options": [{"id": "05996355-8b34-5997-8d0d-935a7139322e", "text": "the word reef alone"}, {"id": "247dba8d-9ea3-5f26-a0cb-54b27aa3a74e", "text": "the time of day"}, {"id": "45a79eb6-5316-534d-a2ad-fe8fed56e55c", "text": "the number of fish"}, {"id": "6416ac29-b2a2-5dc2-b393-4e450ac0466b", "text": "clean and free of litter"}]}, {"id": "9b0afa9f-973e-5369-9032-54e5681fe7aa", "prompt": "Pip was timid, but later greeted everyone with confidence. Timid most likely means what?", "options": [{"id": "5fd0a955-8e6f-557f-8057-a906b7d24c03", "text": "noisy"}, {"id": "8eabf7c5-8bcd-5db2-aba0-4f82761a1b16", "text": "angry"}, {"id": "aaf36407-8a99-5536-a3ad-c34e18db54fb", "text": "shy"}, {"id": "640066ed-e632-5f87-9cc0-5fe758c5ff87", "text": "fearless"}]}]}, "status": "published", "version": 1}, {"id": "c05dcfeb-5e52-51cc-b678-2e017021926a", "owner_id": null, "kind": "game", "title": "Grade 5: Use context clues — Word game", "grade_level": 5, "learning_level": "independent", "summary": "Match four lesson words with their Filipino meanings.", "source_label": "LinguaKids grade pathways · original supplemental enrichment v3", "body": {"cover_scene": 5, "unit_title": "Use context clues", "pairs": [{"en": "pristine", "fil": "malinis at di-nadungisan"}, {"en": "timid", "fil": "mahiyain"}, {"en": "clue", "fil": "pahiwatig"}, {"en": "confidence", "fil": "kumpiyansa"}]}, "status": "published", "version": 1}, {"id": "f0e58460-16b7-5d75-9518-a7f1913d901a", "owner_id": null, "kind": "lesson", "title": "Grade 5: Read between the lines", "grade_level": 5, "learning_level": "independent", "summary": "Four bilingual learning pages with examples and a practice task.", "source_label": "LinguaKids grade pathways · original supplemental enrichment v3", "body": {"cover_scene": 14, "unit_title": "Read between the lines", "pages": [{"english": "An inference is a conclusion based on clues and what you already know. It is more than a guess. Explain which clues support your conclusion.", "filipino": "Ang paghihinuha ay konklusyong batay sa pahiwatig at dati nang kaalaman. Higit ito sa basta hula. Ipaliwanag kung aling mga pahiwatig ang sumusuporta sa konklusyon.", "scene": 14}, {"english": "Read: Pip shivered and pulled his scarf close. Luna brought a warm blanket. The story does not directly say Pip felt cold, but shivering and the blanket support that inference.", "filipino": "Basahin: Nanginig si Pip at hinigpitan ang bandana. Nagdala si Luna ng mainit na kumot. Hindi tuwirang sinabi na nilalamig si Pip, ngunit sinusuportahan ito ng panginginig at kumot.", "scene": 14}, {"english": "A good inference fits the clues. We cannot conclude that Pip hates books from this passage because there is no supporting evidence. If new clues appear, we may need to revise an inference.", "filipino": "Tugma sa mga pahiwatig ang mahusay na hinuha. Hindi natin masasabing ayaw ni Pip sa aklat dahil walang ebidensiya nito sa talata. Maaaring baguhin ang hinuha kapag may bagong pahiwatig.", "scene": 14}, {"english": "Try it: Explain what Pip probably needs and name two clues. Use this pattern: I infer ___ because ___. Keep your conclusion connected to the text.", "filipino": "Subukan: Ipaliwanag kung ano ang malamang na kailangan ni Pip at magbanggit ng dalawang pahiwatig. Gamitin: Nahihinuha kong ___ dahil ___. Iugnay ang konklusyon sa teksto.", "scene": 14}]}, "status": "published", "version": 1}, {"id": "d11548d1-64de-58cf-ac9f-07aaff451ab7", "owner_id": null, "kind": "quiz", "title": "Grade 5: Read between the lines — Quiz", "grade_level": 5, "learning_level": "independent", "summary": "Six questions: vocabulary and applying the lesson. Tap A, B, C, or D.", "source_label": "LinguaKids grade pathways · original supplemental enrichment v3", "body": {"cover_scene": 14, "unit_title": "Read between the lines", "questions": [{"id": "e046f1b4-57d8-5f5d-b93c-78c02d7ca90f", "prompt": "Which Filipino word or phrase means \"inference\"?", "options": [{"id": "343020d4-4936-5b09-81d8-f75dac7c2a85", "text": "ebidensiya"}, {"id": "ef44109e-421a-5b93-8a24-501522bca68b", "text": "konklusyon"}, {"id": "ae64449a-a5ef-562b-96dd-b0091e737a39", "text": "baguhin"}, {"id": "c0dbf784-fb9c-5c97-bb8d-35c4a5bba323", "text": "hinuha"}]}, {"id": "fd849d9c-8ab8-5a00-a6ac-206388aa2172", "prompt": "Which Filipino word or phrase means \"evidence\"?", "options": [{"id": "8fc23b1b-12bc-5918-bd29-62633e68e26c", "text": "konklusyon"}, {"id": "5b904f8a-7592-5b0a-b292-912d7e3269ab", "text": "baguhin"}, {"id": "9179179b-c005-549a-be10-856067d3619c", "text": "ebidensiya"}, {"id": "fa7953a1-4ccf-51a4-acae-0feb0769942c", "text": "hinuha"}]}, {"id": "f9ea2acc-f66c-5494-9df5-50820aff18d1", "prompt": "Which Filipino word or phrase means \"conclusion\"?", "options": [{"id": "235a90d0-0348-5ed2-a2df-fe2b0461ca90", "text": "baguhin"}, {"id": "d97edcad-a296-54a3-8bb6-2eae2d96060e", "text": "konklusyon"}, {"id": "1b582c0f-f400-5817-8f72-3b890d48f1b0", "text": "hinuha"}, {"id": "cc58526d-3101-55c1-a5a0-02741345c9c8", "text": "ebidensiya"}]}, {"id": "b2d6a4d9-144a-5faa-a972-5c49927b16a7", "prompt": "Which Filipino word or phrase means \"revise\"?", "options": [{"id": "ab99a46e-94ce-5234-8eea-0bf7e1ee0ffd", "text": "baguhin"}, {"id": "69f17da9-b915-5551-8e79-211bf133f07f", "text": "hinuha"}, {"id": "58a6adf7-38e2-5145-9bba-8b6ac58eb693", "text": "ebidensiya"}, {"id": "2292ec44-650a-58f1-8164-5f8e18d5a4ad", "text": "konklusyon"}]}, {"id": "cbc6211b-9893-545e-8dba-7dbc6a8242da", "prompt": "What can you infer from Pip shivering and receiving a blanket?", "options": [{"id": "b5a00525-33ea-575f-9edf-008e3a448e4d", "text": "Pip hates books."}, {"id": "752c3a3b-88d7-561a-b675-e967037a3c10", "text": "Pip is underwater."}, {"id": "3dfdbd31-2a6b-557d-8d24-7bd08c784467", "text": "Pip wants to run a race."}, {"id": "a6c2b417-ceed-5f61-b738-83b2e9a3efe5", "text": "Pip feels cold."}]}, {"id": "4cdb071c-0a12-5734-a6fe-4af644f44d69", "prompt": "Which is the strongest reason for an inference?", "options": [{"id": "984e2c07-ed6f-5396-8f10-6a6a58e2a85b", "text": "A friend guessed it."}, {"id": "97b4c775-baa4-5200-8548-93c0d4659178", "text": "It has the longest words."}, {"id": "202f13d7-a97d-5279-939a-7300d214d79f", "text": "Clues in the text support it."}, {"id": "48113310-d0cf-566a-9807-d2da0389fc64", "text": "It is the most surprising answer."}]}]}, "status": "published", "version": 1}, {"id": "9f8e58e7-7152-55f6-aefa-db3258f474ca", "owner_id": null, "kind": "game", "title": "Grade 5: Read between the lines — Word game", "grade_level": 5, "learning_level": "independent", "summary": "Match four lesson words with their Filipino meanings.", "source_label": "LinguaKids grade pathways · original supplemental enrichment v3", "body": {"cover_scene": 14, "unit_title": "Read between the lines", "pairs": [{"en": "inference", "fil": "hinuha"}, {"en": "evidence", "fil": "ebidensiya"}, {"en": "conclusion", "fil": "konklusyon"}, {"en": "revise", "fil": "baguhin"}]}, "status": "published", "version": 1}, {"id": "e641a830-31d4-5510-8f63-d735384ab2f7", "owner_id": null, "kind": "lesson", "title": "Grade 6: Fact, opinion, and reliable evidence", "grade_level": 6, "learning_level": "independent", "summary": "Four bilingual learning pages with examples and a practice task.", "source_label": "LinguaKids grade pathways · original supplemental enrichment v3", "body": {"cover_scene": 4, "unit_title": "Fact, opinion, and reliable evidence", "pages": [{"english": "A fact can be checked with reliable evidence. An opinion expresses a belief, preference, or judgment. An opinion can be thoughtful, but it is not proven simply because someone states it confidently.", "filipino": "Masusuri gamit ang maaasahang ebidensiya ang katotohanan. Nagpapahayag ng paniniwala, kagustuhan, o paghatol ang opinyon. Maaaring makabuluhan ang opinyon, ngunit hindi ito napapatunayan dahil lamang sa tiwalang pagkakasabi.", "scene": 4}, {"english": "Read: An octopus has eight arms. This is a claim we can verify with a reliable reference. Purple is the prettiest color is an opinion because prettiest depends on a person’s preference.", "filipino": "Basahin: May walong galamay ang pugita. Pahayag itong maaaring tiyakin sa maaasahang sanggunian. Opinyon ang Pinakamaganda ang lila dahil nakabatay sa kagustuhan ng tao ang pinakamaganda.", "scene": 4}, {"english": "A checkable claim may still be false, so verify it. Consider who created a source, the evidence it gives, and whether other reliable sources agree. A large number of likes is not proof.", "filipino": "Maaaring mali pa rin ang isang nasusuring pahayag kaya tiyakin ito. Isaalang-alang ang gumawa ng sanggunian, ebidensiyang ibinigay, at pagsang-ayon ng iba pang maaasahang sanggunian. Hindi patunay ang dami ng likes.", "scene": 4}, {"english": "Try it: Write one checkable statement and one opinion about animals. Explain how you would verify the statement. Ask a trusted adult before opening unfamiliar websites.", "filipino": "Subukan: Sumulat ng isang nasusuring pahayag at isang opinyon tungkol sa hayop. Ipaliwanag kung paano titiyakin ang pahayag. Humingi ng tulong sa nakatatanda bago bumukas ng di-pamilyar na website.", "scene": 4}]}, "status": "published", "version": 1}, {"id": "089c42c7-ed00-5e33-b7a9-89f303e7abb0", "owner_id": null, "kind": "quiz", "title": "Grade 6: Fact, opinion, and reliable evidence — Quiz", "grade_level": 6, "learning_level": "independent", "summary": "Six questions: vocabulary and applying the lesson. Tap A, B, C, or D.", "source_label": "LinguaKids grade pathways · original supplemental enrichment v3", "body": {"cover_scene": 4, "unit_title": "Fact, opinion, and reliable evidence", "questions": [{"id": "bc56c5a5-3ae7-5cdb-9711-fb73f3e4d480", "prompt": "Which Filipino word or phrase means \"fact\"?", "options": [{"id": "ec128bcf-612b-5d5e-9e4f-5c96eb3e80a6", "text": "maaasahan"}, {"id": "e37400ac-7b12-50f7-bc8a-9d754c0405c9", "text": "sanggunian"}, {"id": "863cd467-19c4-5dc0-b552-04ff0dcbb1c6", "text": "katotohanan"}, {"id": "01ab62a9-5864-5936-8f73-70f703f91309", "text": "opinyon"}]}, {"id": "51a63b50-c2cf-5fde-a596-f8615092faf1", "prompt": "Which Filipino word or phrase means \"opinion\"?", "options": [{"id": "e1a9383d-3755-5d0a-a5d3-39b550603b58", "text": "sanggunian"}, {"id": "af0c2beb-acef-5a22-ab17-edcd4c1b4788", "text": "opinyon"}, {"id": "42fe56ee-b066-507e-bd18-28c14dad9348", "text": "katotohanan"}, {"id": "fd8ba43c-8eac-5753-84dd-cb0e903c15f1", "text": "maaasahan"}]}, {"id": "70e2c1de-3283-50e2-a885-b531321b225a", "prompt": "Which Filipino word or phrase means \"reliable\"?", "options": [{"id": "aec86f5b-81e5-5bf2-9376-d974f59aac8d", "text": "maaasahan"}, {"id": "0963b7a3-9ea1-5411-b648-fed41aab6996", "text": "katotohanan"}, {"id": "e65a2d93-0e32-5a27-bb00-545e613d459a", "text": "opinyon"}, {"id": "12929fd9-cb9a-5b74-848b-2c5de5988b3c", "text": "sanggunian"}]}, {"id": "5573eb7f-91f7-5b40-bdcc-d3511713d883", "prompt": "Which Filipino word or phrase means \"source\"?", "options": [{"id": "cad98d5a-0dcf-52ce-9958-26426b69c8d9", "text": "katotohanan"}, {"id": "73a1deb2-a03e-54b5-83e0-ab3c200eaae9", "text": "opinyon"}, {"id": "977595a4-bd46-5756-8c50-b1e7749acf45", "text": "maaasahan"}, {"id": "07a8a50a-7c91-50f7-a6d1-1f2c01c70d9a", "text": "sanggunian"}]}, {"id": "37255171-31b2-5ffe-abb8-e34baa605f5e", "prompt": "Which statement is an opinion?", "options": [{"id": "d397ccc7-89ce-5e87-9ffb-d577545297ca", "text": "A week has seven days."}, {"id": "85d91974-4e6e-528f-b444-9de368580c0a", "text": "A triangle has three sides."}, {"id": "81eaadf7-c0b0-5c22-959f-6a6ce0532917", "text": "Purple is the prettiest color."}, {"id": "a0320b33-5956-58fb-a632-6a9e7b2f8426", "text": "An octopus has eight arms."}]}, {"id": "14c8078c-63ee-57e3-921d-9876fdc04508", "prompt": "What is the best way to check an animal claim?", "options": [{"id": "20826384-c8ed-50e1-bd88-d90a0540283a", "text": "Choose the funniest explanation."}, {"id": "365cd5b1-f525-5ea6-aa31-d9a7e4064b6a", "text": "Consult a reliable reference and its evidence."}, {"id": "9b597a81-bdda-5a74-bd00-4f05bc49f184", "text": "Count its likes online."}, {"id": "7fc62ed5-717d-517d-9b6c-deb51382cb01", "text": "Trust the largest font."}]}]}, "status": "published", "version": 1}, {"id": "68d0c861-7392-5943-a8ee-216343f7e018", "owner_id": null, "kind": "game", "title": "Grade 6: Fact, opinion, and reliable evidence — Word game", "grade_level": 6, "learning_level": "independent", "summary": "Match four lesson words with their Filipino meanings.", "source_label": "LinguaKids grade pathways · original supplemental enrichment v3", "body": {"cover_scene": 4, "unit_title": "Fact, opinion, and reliable evidence", "pairs": [{"en": "fact", "fil": "katotohanan"}, {"en": "opinion", "fil": "opinyon"}, {"en": "reliable", "fil": "maaasahan"}, {"en": "source", "fil": "sanggunian"}]}, "status": "published", "version": 1}, {"id": "331e600d-e391-501e-809c-aa24c44f1035", "owner_id": null, "kind": "lesson", "title": "Grade 6: Build a claim with reasons", "grade_level": 6, "learning_level": "independent", "summary": "Four bilingual learning pages with examples and a practice task.", "source_label": "LinguaKids grade pathways · original supplemental enrichment v3", "body": {"cover_scene": 6, "unit_title": "Build a claim with reasons", "pages": [{"english": "A claim is an idea you want readers to accept. Reasons explain why the claim makes sense. Evidence supports those reasons with facts, observations, or trustworthy information.", "filipino": "Ang paninindigan ay ideyang nais mong tanggapin ng mambabasa. Ipinapaliwanag ng mga dahilan kung bakit ito makatuwiran. Sinusuportahan ng ebidensiya ang dahilan gamit ang katotohanan, obserbasyon, o mapagkakatiwalaang impormasyon.", "scene": 6}, {"english": "Claim: Our class should reduce litter. Reason: Litter can harm animals. Evidence: During the class cleanup, volunteers counted twenty pieces of plastic beside the pond. The observation supports a local need for action.", "filipino": "Paninindigan: Dapat bawasan ng klase ang kalat. Dahilan: Maaaring makapinsala sa hayop ang kalat. Ebidensiya: Sa paglilinis ng klase, nakabilang ang mga boluntaryo ng dalawampung plastik sa tabi ng lawa. Sinusuportahan ng obserbasyon ang pangangailangan ng pagkilos.", "scene": 6}, {"english": "A reason must relate to the claim. The library has purple cushions does not explain why we should reduce pond litter. Consider other viewpoints respectfully, and avoid pretending one observation proves every possible case.", "filipino": "Dapat kaugnay ng paninindigan ang dahilan. Hindi naipapaliwanag ng mga lilang unan sa aklatan kung bakit dapat bawasan ang kalat sa lawa. Igalang ang ibang pananaw at huwag ipagpalagay na pinatutunayan ng isang obserbasyon ang lahat ng sitwasyon.", "scene": 6}, {"english": "Try it: Make a claim about caring for a shared place. Give a relevant reason and describe evidence you could collect safely with an adult. Separate what you observed from what you believe.", "filipino": "Subukan: Magbigay ng paninindigan tungkol sa pangangalaga sa lugar na ginagamit ng marami. Magbigay ng kaugnay na dahilan at ebidensiyang ligtas na makakalap kasama ang nakatatanda. Ihiwalay ang napagmasdan sa pinaniniwalaan.", "scene": 6}]}, "status": "published", "version": 1}, {"id": "f40b2240-40aa-52c3-b4ad-9bf41c3da793", "owner_id": null, "kind": "quiz", "title": "Grade 6: Build a claim with reasons — Quiz", "grade_level": 6, "learning_level": "independent", "summary": "Six questions: vocabulary and applying the lesson. Tap A, B, C, or D.", "source_label": "LinguaKids grade pathways · original supplemental enrichment v3", "body": {"cover_scene": 6, "unit_title": "Build a claim with reasons", "questions": [{"id": "a665b9f2-81f5-57ed-8ac1-cf13f00fd1a3", "prompt": "Which Filipino word or phrase means \"claim\"?", "options": [{"id": "1d889842-4c7c-5c62-aac0-5dc89c1c08c3", "text": "obserbasyon"}, {"id": "73e197df-f34c-5ebe-9f1e-aa25fab79b2d", "text": "pananaw"}, {"id": "b05f518e-a561-5f30-8b43-47ac38753f00", "text": "paninindigan"}, {"id": "bb801ded-6d49-561c-bc08-36d85cbec2c1", "text": "dahilan"}]}, {"id": "a13ede86-8ebe-5786-826f-8fb9be1d30e9", "prompt": "Which Filipino word or phrase means \"reason\"?", "options": [{"id": "b2f97215-3a07-5322-87f3-7c5192c60904", "text": "pananaw"}, {"id": "ea2a83a5-c8bf-5158-9bf8-533843f597b2", "text": "dahilan"}, {"id": "f0573a1a-722e-5420-b5e7-35b9adc39e24", "text": "paninindigan"}, {"id": "74db0d32-6e14-55bd-8c13-a0255f446d79", "text": "obserbasyon"}]}, {"id": "9e407b0a-d814-5473-ae54-3bf5223f3a22", "prompt": "Which Filipino word or phrase means \"observation\"?", "options": [{"id": "63810ee9-3bb7-501b-a13c-630ba5b56f3d", "text": "obserbasyon"}, {"id": "a41bbe3f-e84b-55c2-ba4d-cda8da6127a3", "text": "paninindigan"}, {"id": "a167b6bb-d084-51ad-aa1e-49b8799e5e25", "text": "dahilan"}, {"id": "b912de57-4b9c-567e-a075-37d38581a02d", "text": "pananaw"}]}, {"id": "e064e4ea-1b2f-52db-a9fb-a56064c32891", "prompt": "Which Filipino word or phrase means \"viewpoint\"?", "options": [{"id": "0588242d-e566-587d-a586-f40e8f497de4", "text": "paninindigan"}, {"id": "1dfc5122-8a69-5155-a59c-07ae35c58945", "text": "dahilan"}, {"id": "34fdb9cc-45cf-5b94-ae19-fcfbc6600fc4", "text": "obserbasyon"}, {"id": "2dd96171-72ba-59fa-9198-7a6f65a39489", "text": "pananaw"}]}, {"id": "c4bda957-6d08-5c75-a731-c20a75135d9e", "prompt": "Which evidence best supports reducing litter near the pond?", "options": [{"id": "87a33e15-08ef-56d0-bb2b-65071010ee6e", "text": "Finn prefers apples."}, {"id": "a252c8fe-6185-53a5-b8de-052e3d708514", "text": "The classroom clock is round."}, {"id": "46c0b7b3-4c30-57ed-955a-13addefd1fd8", "text": "Volunteers counted plastic beside the pond."}, {"id": "88564368-53db-55e4-a25c-8fc960998a56", "text": "The library has purple cushions."}]}, {"id": "5461a0a0-cf81-5d62-85b7-6dfd9c04eb3b", "prompt": "Which part explains why a claim makes sense?", "options": [{"id": "bd031395-95da-5fa0-bda4-d2607610584e", "text": "a random number"}, {"id": "52ce6bd0-dddf-52df-909a-aeff732d15fb", "text": "a relevant reason"}, {"id": "296c6590-2833-5ebb-9a4d-3bb4f32005a9", "text": "an unrelated joke"}, {"id": "f72c1d0a-6402-577b-bd81-25509d7b240b", "text": "a decorative title"}]}]}, "status": "published", "version": 1}, {"id": "05550c24-0c05-58eb-b511-f4d7b61afe8b", "owner_id": null, "kind": "game", "title": "Grade 6: Build a claim with reasons — Word game", "grade_level": 6, "learning_level": "independent", "summary": "Match four lesson words with their Filipino meanings.", "source_label": "LinguaKids grade pathways · original supplemental enrichment v3", "body": {"cover_scene": 6, "unit_title": "Build a claim with reasons", "pairs": [{"en": "claim", "fil": "paninindigan"}, {"en": "reason", "fil": "dahilan"}, {"en": "observation", "fil": "obserbasyon"}, {"en": "viewpoint", "fil": "pananaw"}]}, "status": "published", "version": 1}, {"id": "b8646b59-85cb-563c-8b76-e2a3e2fd0963", "owner_id": null, "kind": "lesson", "title": "Grade 6: Figurative language and careful meaning", "grade_level": 6, "learning_level": "independent", "summary": "Four bilingual learning pages with examples and a practice task.", "source_label": "LinguaKids grade pathways · original supplemental enrichment v3", "body": {"cover_scene": 13, "unit_title": "Figurative language and careful meaning", "pages": [{"english": "Figurative language creates a picture beyond a word’s literal meaning. A simile compares using like or as. A metaphor describes one thing as another to suggest a shared quality.", "filipino": "Lumilikha ang matalinghagang wika ng larawang higit sa literal na kahulugan. Gumagamit ng tulad o parang ang pagtutulad. Inilalarawan naman ng pagwawangis ang isang bagay bilang iba upang ipakita ang magkaparehong katangian.", "scene": 13}, {"english": "Read: The fireflies shone like tiny lanterns. This simile compares their light to lanterns. Read: The library was a warm hug. This metaphor suggests comfort; the building does not have arms.", "filipino": "Basahin: Kuminang ang mga alitaptap na parang munting parol. Inihahambing ng pagtutulad ang liwanag nila sa parol. Basahin: Isang mainit na yakap ang aklatan. Ipinapahiwatig ng pagwawangis ang ginhawa; walang mga bisig ang gusali.", "scene": 13}, {"english": "Personification gives human actions or qualities to something nonhuman: The wind whispered through the leaves. Wind does not literally speak. Use the context to explain the effect on the reader.", "filipino": "Nagbibigay ng kilos o katangiang pantao sa hindi tao ang pagsasatao: Bumulong ang hangin sa mga dahon. Hindi literal na nagsasalita ang hangin. Gamitin ang konteksto upang ipaliwanag ang epekto sa mambabasa.", "scene": 13}, {"english": "Try it: Write a simile about moonlight and a metaphor about friendship. Explain each comparison in plain language. Make sure you can distinguish an imaginative description from a factual claim.", "filipino": "Subukan: Sumulat ng pagtutulad tungkol sa liwanag ng buwan at pagwawangis tungkol sa pagkakaibigan. Ipaliwanag ang bawat paghahambing sa payak na salita. Ihiwalay ang malikhaing paglalarawan sa makatotohanang pahayag.", "scene": 13}]}, "status": "published", "version": 1}, {"id": "5a99dec2-f159-5dfc-9957-8a3f918deda8", "owner_id": null, "kind": "quiz", "title": "Grade 6: Figurative language and careful meaning — Quiz", "grade_level": 6, "learning_level": "independent", "summary": "Six questions: vocabulary and applying the lesson. Tap A, B, C, or D.", "source_label": "LinguaKids grade pathways · original supplemental enrichment v3", "body": {"cover_scene": 13, "unit_title": "Figurative language and careful meaning", "questions": [{"id": "78782dfe-5390-5a70-bc1f-298f70a10815", "prompt": "Which Filipino word or phrase means \"simile\"?", "options": [{"id": "41ce63c0-1bb1-5b14-8d7c-0d77a66b4290", "text": "pagsasatao"}, {"id": "762d8321-06e7-5ab3-9c43-71f2501163fb", "text": "tuwiran"}, {"id": "5e322e11-0a42-55db-bee9-fc773e906c5b", "text": "pagtutulad"}, {"id": "53ecd69e-1d74-5237-b16a-a8d1573d207b", "text": "pagwawangis"}]}, {"id": "099620e7-62d9-521f-af7e-6d9843c20ad5", "prompt": "Which Filipino word or phrase means \"metaphor\"?", "options": [{"id": "91b58ba6-7efe-5401-a49a-523c13e86268", "text": "tuwiran"}, {"id": "6cc646ce-d0fd-57cc-833d-569f22afa4d1", "text": "pagwawangis"}, {"id": "b3b503d8-cceb-51fd-88ef-8f95a7944eff", "text": "pagtutulad"}, {"id": "8af0d881-127b-5312-9dd6-8929f43ba188", "text": "pagsasatao"}]}, {"id": "c7fb39be-4df9-509d-acaf-fdbeeaa87963", "prompt": "Which Filipino word or phrase means \"personification\"?", "options": [{"id": "2b710b67-af18-53d4-b8ff-35aa9d736a9d", "text": "pagsasatao"}, {"id": "3ae79c5a-842b-5c10-81c0-7c6d66e5b304", "text": "pagtutulad"}, {"id": "bac745b7-6b62-5e87-9a0b-b3f46578d937", "text": "pagwawangis"}, {"id": "2b548e4a-4633-5970-aa77-0e76eeb3734b", "text": "tuwiran"}]}, {"id": "d59eac93-e6d9-5f6b-852e-202e9a975692", "prompt": "Which Filipino word or phrase means \"literal\"?", "options": [{"id": "d0337edf-dbb5-5425-aaa8-03d9a49a8b24", "text": "pagtutulad"}, {"id": "0f733b97-1f7b-5633-9fcd-5a93d76ad06e", "text": "pagwawangis"}, {"id": "c848bd3e-03ef-5003-a427-fa1a7a194791", "text": "pagsasatao"}, {"id": "29259458-dd8c-5116-9215-3846b22f94e0", "text": "tuwiran"}]}, {"id": "988dae5c-fdbe-59c6-a681-42327c8d2ce5", "prompt": "Which sentence is a simile?", "options": [{"id": "854514ea-6a72-5c4a-b5eb-3f1b383c0c82", "text": "The library opens at nine."}, {"id": "93988c1b-5eb7-51b7-b833-97dca7a7ae63", "text": "Pip has a red scarf."}, {"id": "23cf5f42-1bd6-5899-a2bc-afe97aae1fdd", "text": "The fireflies shone like tiny lanterns."}, {"id": "44fe2346-e429-5c2c-8f69-9493d6db7b13", "text": "The fireflies have wings."}]}, {"id": "8a4488b7-7776-5a71-a9d4-b0252e164b82", "prompt": "What does The library was a warm hug suggest?", "options": [{"id": "a1682a29-7e78-5632-b6ad-c76f6f16bee0", "text": "The library could walk."}, {"id": "70ff7c5c-bf29-5812-bf93-2cf12867f1f0", "text": "The library felt comforting."}, {"id": "705c2c93-7ca4-5fbe-ba69-a00f5f306d15", "text": "The building grew arms."}, {"id": "cf833c1b-acc2-584d-ab19-c14409b5205b", "text": "Every book was hot."}]}]}, "status": "published", "version": 1}, {"id": "4316b61a-4e00-576c-a876-2e101f63c9d1", "owner_id": null, "kind": "game", "title": "Grade 6: Figurative language and careful meaning — Word game", "grade_level": 6, "learning_level": "independent", "summary": "Match four lesson words with their Filipino meanings.", "source_label": "LinguaKids grade pathways · original supplemental enrichment v3", "body": {"cover_scene": 13, "unit_title": "Figurative language and careful meaning", "pairs": [{"en": "simile", "fil": "pagtutulad"}, {"en": "metaphor", "fil": "pagwawangis"}, {"en": "personification", "fil": "pagsasatao"}, {"en": "literal", "fil": "tuwiran"}]}, "status": "published", "version": 1}]''';
